window.GENSHIN_STORY = {"schema":1,"volumes":[{"version":"1.0","major":1,"minor":0,"title":"序章第一至三幕；第一章第一至二幕","chapter":"序章第1至3幕与第一章第1至2幕","sections":[{"id":"v1.0-s0","title":"序章第一幕：捕风的异乡人","kind":"chapter","html":"\u003cp\u003e双子曾一同游历诸多世界。准备离开提瓦特时，他们被一位陌生的神明截住。交锋中，兄妹失散，旅行者的力量被封印。漫长的沉睡之后，旅行者在海边救起派蒙；从此，一人为寻找血亲，一人作向导，踏上拜访七神的道路。\u003c/p\u003e\n\u003cp\u003e他们在蒙德的风神像前获得风元素之力，又在低语森林撞见一名吟游诗人与巨龙相会。诗人似乎想安抚巨龙，旅行者却无意惊动了它，只留下染着不祥气息的泪滴结晶。侦察骑士安柏把两人引入自由之城。就在他们初见城邦时，被称为「风魔龙」的巨龙掀起风暴。旅行者借风而起，击退了它，也被西风骑士团的琴团长注意到。琴、凯亚与丽莎调查后发现，城外「四风守护」的庙宇力量正受扰乱；旅行者协助清除异常，得以参与蒙德的危机。\u003c/p\u003e\n","readingMinutes":1},{"id":"v1.0-s1","title":"序章第二幕：为了没有眼泪的明天","kind":"chapter","html":"\u003cp\u003e骑士团希望救下巨龙：它原名特瓦林，曾是蒙德的守护者。愚人众外交官则提出杀龙方案，至冬国也开始介入危机。旅行者手中的结晶会伤害神之眼的持有者；神之眼是凡人用来引导元素力的魔力器官。旅行者能安全地将结晶净化，让那名吟游诗人——温迪——看见拯救特瓦林的可能。\u003c/p\u003e\n\u003cp\u003e温迪说明，特瓦林长期受毒血与深渊教团的影响，误以为自己遭人背弃；他想用旧日的「天空之琴」唤回龙的记忆。取琴时，愚人众抢先一步，旅行者与温迪反被误作窃贼。晨曦酒庄的迪卢克暗中接应，琴也暂放下代理团长的身份加入他们。温迪向众人表明自己风神巴巴托斯的身份。众人夺回琴，以净化的龙泪修复它，在摘星崖唤来了特瓦林。然而深渊法师现身，重新挑起龙的猜疑；琴弦折断，特瓦林飞向被结界封锁的旧蒙德遗迹。\u003c/p\u003e\n","readingMinutes":1},{"id":"v1.0-s2","title":"序章第三幕：巨龙与自由之歌","kind":"chapter","html":"\u003cp\u003e迪卢克追出深渊法师的行踪，温迪由此找到突破封锁的办法。众人进入风龙废墟，追上特瓦林，旅行者清除了折磨它的毒与深渊力量。获救的特瓦林问温迪，为何不再要求自己履行守护者的职责。温迪请它依自己的意志决定去留，蒙德的风灾得以平息。\u003c/p\u003e\n\u003cp\u003e胜利之后，另一场袭击毫无预警地发生。温迪在教堂外遭愚人众执行官「女士」伏击，被夺走体内的\u003cstrong\u003e神之心\u003c/strong\u003e。旅行者也被制服。随后在风起地，温迪解释，神之心是神明与天空岛共鸣相连的魔力器官；持有神之眼的凡人也有登上天空岛、成为神明的资格，被称为「原神」。他提到，五百年前的一场灾厄改变了自己与冰之女皇的关系，却没有说出女皇收集神之心的目的。他指引旅行者前往璃月，赶上岩神一年一度的请仙典仪。\u003c/p\u003e\n","readingMinutes":1},{"id":"v1.0-s3","title":"第一章第一幕：浮世浮生千岩间","kind":"chapter","html":"\u003cp\u003e旅行者赶到璃月港，本以为能向岩王帝君问路，却在请仙典仪上亲眼看见神明的躯体从天而降。天权星凝光下令封锁现场，来自异乡的旅行者险些被当成嫌疑人。出手解围的是愚人众执行官「公子」达达利亚。他自称并无敌意，交给旅行者百无禁忌箓，让他们把帝君遇害的消息先告知仙人。\u003c/p\u003e\n\u003cp\u003e旅行者先后见到削月筑阳真君、理水叠山真君、留云借风真君与降魔大圣魈。仙人们对帝君之死震惊且愤怒，璃月七星却紧锁帝君遗体，不容外人查验。仙人与人治的璃月之间，猜疑开始增长。公子看似帮助旅行者洗清嫌疑，实则也在留意他们为何执意要见神明。\u003c/p\u003e\n","readingMinutes":1},{"id":"v1.0-s4","title":"第一章第二幕：辞行久远之躯","kind":"chapter","html":"\u003cp\u003e公子把旅行者引荐给往生堂客卿钟离。钟离要为「岩王帝君」筹办送仙典仪，旅行者则希望借此接近帝君的仙体。于是三人穿行璃月市井，选取夜泊石、调制霓裳花香膏、向萍姥姥借涤尘铃、备下纸鸢，又为不卜庐寻找永生香。钟离熟知古礼、仙人与岩神的往事，却常忘带摩拉；费用多由公子承担。\u003c/p\u003e\n\u003cp\u003e公子一面支付典仪费用，一面打听帝君仙体的下落。他得知仙体被藏在黄金屋，又向旅行者试探消息，遭到拒绝。与此同时，凝光邀请旅行者登上群玉阁。送仙典仪尚未开始，帝君之死仍待调查。\u003c/p\u003e\n","readingMinutes":1},{"id":"v1.0-s5","title":"同期世界线索","kind":"world","html":"\u003cul\u003e\n\u003cli\u003e\u003cstrong\u003e「时与风」\u003c/strong\u003e：蒙德外海无名小岛的日晷与千风神殿留下时间和风相连的古老痕迹。遗迹的主人和完整历史仍待查明。\u003c/li\u003e\n\u003cli\u003e\u003cstrong\u003e「古云有螭」与「靖世九柱」\u003c/strong\u003e：璃月山野散有被封印的古老力量与遗迹。它们说明帝君与仙人守护的土地，曾经历远不止眼前这场政治危机的战争。\u003c/li\u003e\n\u003cli\u003e\u003cstrong\u003e已知的三股势力\u003c/strong\u003e：西风骑士团试图救龙，深渊教团操纵龙的痛苦，愚人众则追逐神之心。三者目的并不相同；到此时，旅行者尚不知深渊教团的统领是谁，也不知冰之女皇收集神之心究竟为了什么。\u003c/li\u003e\n\u003c/ul\u003e\n","readingMinutes":1},{"id":"v1.0-s6","title":"此刻悬而未决","kind":"question","html":"\u003cp\u003e血亲身在何处？陌生神明是谁？冰之女皇为何收集神之心？璃月的岩王帝君究竟为何坠落？\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.0\"\u003e1.0 版本收录任务\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Outlander_Who_Caught_the_Wind\"\u003e捕风的异乡人\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/For_a_Tomorrow_Without_Tears\"\u003e为了没有眼泪的明天\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Song_of_the_Dragon_and_Freedom\"\u003e巨龙与自由之歌\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E5%B0%BE%E5%A3%B0%E7%9A%84%E5%B0%BE%E5%A3%B0\"\u003e「尾声的尾声」任务对话：神之眼与神之心\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Of_the_Land_Amidst_Monoliths\"\u003e浮世浮生千岩间\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Farewell,_Archaic_Lord\"\u003e辞行久远之躯\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.1","major":1,"minor":1,"title":"第一章第三幕：迫近的客星","chapter":"第一章第三幕","sections":[{"id":"v1.1-sintro","title":"第一章第三幕：迫近的客星","kind":"chapter","html":"\u003cp\u003e旅行者应凝光之邀登上群玉阁，从她收集的情报中找到调查方向，随后发现愚人众正在大量仿制百无禁忌箓。与此同时，仙人与璃月七星因帝君的「遇害」几乎兵戎相见。钟离仍在准备送仙典仪，似乎置身风暴之外。\u003c/p\u003e\n\u003cp\u003e公子趁乱闯入黄金屋，目标是岩王帝君仙体中的神之心。旅行者赶到，双方交手；公子先后动用邪眼和魔王武装，仍未得逞。当他从仙体中探取神之心却一无所获时，便误疑旅行者先行取走了它。受挫后，他动用仿制的符箓唤醒被岩神镇压于孤云阁海底的漩涡之魔神奥赛尔，企图逼真正的岩神现身。璃月港立刻面临灭顶之灾。\u003c/p\u003e\n\u003cp\u003e凝光、刻晴、众仙人与旅行者暂释分歧，在群玉阁上以归终机迎击奥赛尔。愚人众袭击炮台，旅行者在仙人相助下守住阵地；然而魔神的反击摧毁了炮台。凝光最终舍弃自己经营多年的空中宫殿，以坠落的群玉阁重创奥赛尔，将其重新压回海中。这一战既是璃月人的胜利，也迫使仙人承认：帝君不在场时，凡人仍能守护这座港口。\u003c/p\u003e\n\u003cp\u003e战后，旅行者在北国银行撞见钟离、女士和公子。钟离承认自己就是岩神摩拉克斯；请仙典仪上的「死亡」由他亲自安排。他想用一次真正的危机检验璃月是否已能告别神明的直接统治，并预留了若人们失败就出手的后路。结果使他确信，璃月进入了人的时代。作为与冰之女皇订下的「终结一切契约的契约」的一部分，他把神之心交给女士。契约的交换条件，他没有说出；公子也发现自己被同僚与岩神蒙在鼓里。\u003c/p\u003e\n\u003cp\u003e送仙典仪终于举行。璃月人以自己的方式纪念岩王帝君，钟离则以往生堂客卿的身份继续生活。刻晴询问旅行者想要什么报酬，旅行者请她帮忙张贴寻找血亲的启事。钟离指向下一站稻妻：那里的雷神推行「眼狩令」，国家又被风暴与锁国政策封闭。\u003c/p\u003e\n","readingMinutes":2},{"id":"v1.1-s0","title":"此刻悬而未决","kind":"question","html":"\u003cp\u003e冰之女皇用什么换取了钟离的神之心？她收集神之心的最终目的是什么？\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_New_Star_Approaches\"\u003e迫近的客星任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.1\"\u003e1.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.2","major":1,"minor":2,"title":"无魔神任务：龙脊雪山与白垩之子","chapter":"无主线","sections":[{"id":"v1.2-s0","title":"无魔神任务：龙脊雪山与白垩之子","kind":"chapter","html":"\u003cp\u003e蒙德南方的龙脊雪山埋着巨龙杜林的遗骸。它曾在数百年前袭击蒙德，最终被特瓦林击败；至今，山中的地脉与遗骨仍带着诡异的活性。旅行者受炼金术士阿贝多之邀，参与对一柄奇异魔剑的观察。剑与杜林残留的力量彼此呼应，似乎能吸收雪山的生命能量。阿贝多反复测试旅行者的元素亲和力和抗侵蚀能力，既像严谨的学者，也像在寻找一面能映照自己秘密的镜子。\u003c/p\u003e\n\u003cp\u003e阿贝多谈起老师莱茵多特，也对自己可能失控的危险抱有警惕。他请旅行者答应：倘若自己有朝一日危害蒙德，就出手阻止。旅行者记下了这个请求，阿贝多的身世与他对杜林的关注仍有许多疑点。\u003c/p\u003e\n\u003cp\u003e雪山的探索也揭开另一层历史：古国沙尔·芬德尼尔曾在此存续，后来在严寒、灾变与神秘的天外之物影响下覆灭。如今看似荒凉的山地，曾是有人祈祷、建城与记述命运的地方。古国覆灭的完整因果，此时仍未清楚。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.2\"\u003e1.2 版本任务列表\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Dragonspine\"\u003e龙脊雪山\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Chalk_Prince_and_the_Dragon\"\u003e白垩与黑龙\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.3","major":1,"minor":3,"title":"第一章第四幕·序幕：拾枝者·戴因斯雷布","chapter":"第一章第四幕序幕","sections":[{"id":"v1.3-sintro","title":"第一章第四幕·序幕：拾枝者·戴因斯雷布","kind":"chapter","html":"\u003cp\u003e旅行者在蒙德受冒险家协会所托，追查与深渊教团有关的线索，于是结识了戴因斯雷布。此人不属于骑士团，也不急于说明自己的来历；他熟悉深渊教团的行动，却对七神抱有显著戒心。他向旅行者提出问题，像在衡量这个寻找血亲的异乡人会如何看待神、土地与自身命运。\u003c/p\u003e\n\u003cp\u003e两人走过蒙德的遗迹与风龙废墟，追寻深渊使徒的踪迹。戴因斯雷布谈起曾与自己同行的旅伴，旅行者也短暂感到失散血亲仿佛就在附近。两人继续搜寻，却未能找到对方。\u003c/p\u003e\n","readingMinutes":1},{"id":"v1.3-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e海灯节期间，旅行者见到魈日夜清除魔神残留的怨念。璃月港已恢复安宁，山野中的邪祟仍需夜叉镇压。旅行者帮他处理这些威胁，也邀他在节日里稍作停留。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.3\"\u003e1.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Bough_Keeper:_Dainsleif\"\u003e拾枝者·戴因斯雷布\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.4","major":1,"minor":4,"title":"第一章第四幕：我们终将重逢","chapter":"第一章第四幕","sections":[{"id":"v1.4-s0","title":"第一章第四幕：我们终将重逢","kind":"chapter","html":"\u003cp\u003e一桩寻宝委托，把旅行者引入深渊教团盘踞的遗迹。倒悬的风神像、死去的盗宝团成员与突然现身的深渊使徒，让这次调查显出近乎亵渎神明的意味。戴因斯雷布再度加入追查。众人从教团文书中拼出计划：以昔日岩神封印的奥赛尔为素材，以倒悬神像为躯干，再装入第一台「耕地机」的眼睛，造出能够与天上力量抗衡的机械神明。\u003c/p\u003e\n\u003cp\u003e戴因斯雷布这才说出「耕地机」的真正来历。它们就是散落提瓦特各地的遗迹守卫，曾是无神之国坎瑞亚的战争机器。约五百年前，坎瑞亚覆灭；其技术与人民留下的残骸，成了今日许多人眼中的怪物。旅行者因此第一次把眼前的深渊灾祸，与一场被神明毁灭的古国联系起来。\u003c/p\u003e\n\u003cp\u003e为了阻止教团，众人先救下遭仪式侵蚀的北风之狼，随后在风龙废墟找到首台耕地机，戴因斯雷布取走了关键的「眼睛」。他们返回遗迹，准备毁去倒悬神像，深渊使徒却在那里等候。就在戴因斯雷布即将制服对手的一刻，一把熟悉的剑挡下了他——旅行者失散的血亲终于现身。\u003c/p\u003e\n\u003cp\u003e重逢没有带来归家。血亲认识戴因斯雷布，称他为坎瑞亚的「末光之剑」，并指出他因诅咒长生，眼看故国之人化为怪物。血亲如今站在深渊教团一边，认为与「命运」的战争尚未结束；旅行者必须走遍提瓦特，亲眼看见世界的真相，才会理解自己的选择。说罢，血亲随深渊使徒踏入传送门。戴因斯雷布追了进去，旅行者慢了一步，只能眼看入口关闭。\u003c/p\u003e\n\u003cp\u003e血亲仍在提瓦特，却选择与深渊教团同行。旅行者带着对坎瑞亚和五百年前灾难的疑问离开遗迹。派蒙劝他们继续走下去；下一站，仍是雷暴中的稻妻。\u003c/p\u003e\n","readingMinutes":2}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/We_Will_Be_Reunited\"\u003e我们终将重逢任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.4\"\u003e1.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.5","major":1,"minor":5,"title":"无魔神任务：若陀龙王与磨损","chapter":"无主线","sections":[{"id":"v1.5-s0","title":"无魔神任务：若陀龙王与磨损","kind":"chapter","html":"\u003cp\u003e璃月矿工失踪、岩层异动，把旅行者与钟离引向伏龙树。树下封印的是若陀龙王，昔日岩神的盟友。岩神赋予它观世之目，二者曾并肩守护璃月；但若陀与地脉紧密相连，岁月使记忆和情感不断受损。人类开采山脉又加剧了它的痛苦。最终，若陀失去与岩神同行的初心，双方不得不以封印作结。\u003c/p\u003e\n\u003cp\u003e如今，若陀的怨恨化作少女阿鸠，图谋破坏封印；尚存善念的部分则借昆钧之身，帮助钟离与旅行者再次镇压龙王。钟离将长生者逐渐失去记忆、意志与情感的过程称为\u003cstrong\u003e磨损\u003c/strong\u003e。昆钧所承载的旧日情谊也随之散去，钟离再次与故友告别。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.5\"\u003e1.5 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/No_Mere_Stone\"\u003e匪石：钟离传说任务第二幕\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.6","major":1,"minor":6,"title":"第二章·序幕：振袖秋风问红叶","chapter":"第二章序幕","sections":[{"id":"v1.6-sintro","title":"第二章·序幕：振袖秋风问红叶","kind":"chapter","html":"\u003cp\u003e旅行者要去稻妻，却面临横海雷暴与锁国令。稻妻出身的阿幸劝他们三思，最终指向能穿越险海的南十字船队。北斗的「南十字武斗会」提供了船票；旅行者以不借神之眼也能运使元素的身手夺得冠军，同时结识船上的流浪武士枫原万叶。\u003c/p\u003e\n\u003cp\u003e万叶带着一枚失去光芒的神之眼。它属于一位故友：那人向九条裟罗发起御前决斗，败后被雷电将军处决。万叶赶到时，只来得及抢走故友的神之眼，随后逃出稻妻。他四处寻找能令它重新发光的人，希望有人继承故友直面雷霆的愿望。武斗会的奖品被盗，旅行者与万叶追上盗贼，却无人能令那枚神之眼复苏。\u003c/p\u003e\n\u003cp\u003e北斗允诺送旅行者出海。万叶则带着那枚神之眼继续同行。海的另一边，眼狩令仍在执行，违抗者随时可能遭到追捕。\u003c/p\u003e\n","readingMinutes":1},{"id":"v1.6-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e金苹果群岛上，可莉收到「嘟嘟大魔王」的来信，邀旅行者等人一同赴约。谜底揭开后，众人才知道整场冒险由可莉的母亲艾莉丝安排。她通过留音向众人道谢，希望女儿能与朋友们度过一个快乐的夏天。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Autumn_Winds,_Scarlet_Leaves\"\u003e振袖秋风问红叶任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.6\"\u003e1.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.0","major":2,"minor":0,"title":"第二章第一至二幕：不动鸣神，恒常乐土；无念无想，泡影断灭","chapter":"第二章第1至2幕","sections":[{"id":"v2.0-sintro","title":"第二章第一至二幕：不动鸣神，恒常乐土；无念无想，泡影断灭","kind":"chapter","html":"\u003cp\u003e北斗的船穿过雷暴，把旅行者送到稻妻。这里的「锁国令」严控出入，「眼狩令」则要收缴神之眼，嵌进雷电将军的千手百眼神像。旅行者原本只想见雷神寻找血亲线索，社奉行的托马与神里绫华却请他们先看见法令落在人身上的样子。\u003c/p\u003e\n\u003cp\u003e失去神之眼的手岛忘了多年等待的缘由；武士黑泽曾为人垫付粮食，却忘记自己为何负债；以武艺为信念的土门在失去神之眼后几乎崩溃。三人的愿望与记忆都随收缴受损，旅行者因而答应协助绫华。此后，旅行者又与宵宫一起营救被关押的烟花匠。\u003c/p\u003e\n\u003cp\u003e托马随后被选作「第一百枚」神之眼的献祭对象。旅行者冲向仪式，却被雷电将军拖入神秘的「一心净土」，在交战中败下阵来。回到现实后，将军举刀欲杀旅行者，托马挣脱束缚，以投枪打断她的攻击，带旅行者逃离现场。两人随后遭到通缉。\u003c/p\u003e\n\u003cp\u003e旅行者逃往反抗军控制的战线，结识军士哲平，并协助五郎抵御幕府军。九条裟罗率军逼近时，珊瑚宫心海带援兵赶到，迫使幕府军撤退。心海邀请旅行者前往海祇岛，继续商议合作。\u003c/p\u003e\n","readingMinutes":1},{"id":"v2.0-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e「神樱大祓」中，巫女花散里请旅行者清除鸣神岛各处结界中的污秽。她继承了狐斋宫留下的记忆，自己也将在净化完成后消散。旅行者完成仪式，收下她留下的面具。八酝岛上，遭破坏的镇物使奥罗巴斯遗恨化成的祟神肆虐，旅行者也参与修复封印。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务章节与版本记录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.0\"\u003e2.0 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%97%A0%E5%BF%B5%E6%97%A0%E6%83%B3%EF%BC%8C%E6%B3%A1%E5%BD%B1%E6%96%AD%E7%81%AD\"\u003e「无念无想，泡影断灭」任务目录\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.1","major":2,"minor":1,"title":"第二章第三幕：千手百眼，天下人间","chapter":"第二章第三幕","sections":[{"id":"v2.1-sintro","title":"第二章第三幕：千手百眼，天下人间","kind":"chapter","html":"\u003cp\u003e反抗军的战果背后，悄悄流入前线的「邪眼」让普通士兵获得力量，却以生命为代价。哲平想追上旅行者的脚步，使用邪眼后急速衰老，最终死去。旅行者循线闯入愚人众的邪眼工厂，愤怒中遭散兵设局。八重神子拿雷神的神之心换回旅行者的性命。\u003c/p\u003e\n\u003cp\u003e神子告诉旅行者，世人所见的「雷电将军」是奉行永恒程序的人偶，真正的雷神影长久隐居一心净土，并将不再使用的神之心托给她这位旧友与眷属保管。影曾与姐姐真共同守护稻妻；真死后，她惧怕一切终将失去，便以静止来对抗磨损。神子让旅行者接受特训，准备再次进入净土，与影当面交谈。\u003c/p\u003e\n\u003cp\u003e旅行者和神子追查出九条家对将军隐瞒战况、配合愚人众推动眼狩令。九条裟罗知晓真相后决意求证，却在天守阁被女士击倒。旅行者向女士发起御前决斗，并赢下战斗；雷电将军随即按决斗法则斩杀女士。旅行者离开天守阁时，仍遭将军追击。万叶挡在刀前，故友失色的神之眼在危急一刻重新亮起，帮他接住了那道曾夺走友人性命的雷光。\u003c/p\u003e\n\u003cp\u003e旅行者再次进入一心净土，借神子留下的御守与她会合。神子唤起寄宿在神像中的愿望，帮助旅行者抵抗影的力量，也劝影重新注视人们的追求。影在交战后改变决定，废止眼狩令。锁国令仍然有效，她也开始重新思考自己追求的永恒。\u003c/p\u003e\n","readingMinutes":2},{"id":"v2.1-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e清籁岛上，旅行者修复镇石，登上雷暴中心，击败雷音权现。海祇岛则仍供奉死去的奥罗巴斯，居民延续着与鸣神岛不同的信仰和祭祀。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务章节与版本记录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.1\"\u003e2.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E9%9B%B7%E7%94%B5%E5%BD%B1\"\u003e雷电影角色故事：托付神之心\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.2","major":2,"minor":2,"title":"无魔神任务：鹤观的雾与阿瑠","chapter":"无主线","sections":[{"id":"v2.2-s0","title":"无魔神任务：鹤观的雾与阿瑠","kind":"chapter","html":"\u003cp\u003e旅行者踏入终年被雾包围的鹤观，遇到少年阿瑠。他像在等待一场祭典，又似乎不知道岛上的日子早已重复了太久。随着栖木与羽毛的仪式被逐一解开，旅行者看见一段惨烈旧史：鹤观的先民崇奉雷鸟，将能以歌声打动雷鸟的阿瑠献作祭品。他们以为这是虔诚，雷鸟却从未要求这份牺牲。它归来后发现阿瑠已死，在愤怒与悲伤中毁灭鹤观。\u003c/p\u003e\n\u003cp\u003e岛上的浓雾与循环保留着往日的碎片，阿瑠的身影也被困在重复的祭礼里。旅行者带他前往清籁岛，唱出未能传达给雷鸟的歌，随后回到鹤观与他告别。阿瑠留下羽毛，请旅行者替自己看看岛外的世界。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.2\"\u003e2.2 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Through_the_Mists\"\u003e雾海纪行\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.3","major":2,"minor":3,"title":"无魔神任务：皑尘与雪影","chapter":"无主线","sections":[{"id":"v2.3-s0","title":"无魔神任务：皑尘与雪影","kind":"chapter","html":"\u003cp\u003e雪山里出现了与阿贝多容貌相同的身影。旅行者等人追查遇袭和实验笔记失窃的事件，最终与一株拟态为阿贝多的变异骗骗花交战。骗骗花被击败后，阿贝多仍在留意山中的另一名冒牌者。\u003c/p\u003e\n\u003cp\u003e阿贝多以一个炼金术故事解释自己的怀疑：莱茵多特的「原初之人计划」曾有被视作失败品的造物，遭杜林吞食后，又借龙的力量复苏。那个造物可能学会了阿贝多的炼金术，改造骗骗花替自己行动，企图取代阿贝多。旅行者亲眼击败了骗骗花，另一名造物的去向仍有疑点。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.3\"\u003e2.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Shadows_Amidst_Snowstorms\"\u003e皑尘与雪影\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%81%B0%E4%B8%AD%E4%B9%8B%E7%A7%98\"\u003e「灰中之秘」任务正文\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.4","major":2,"minor":4,"title":"间章第一幕：风起鹤归；渊下宫","chapter":"间章第一幕","sections":[{"id":"v2.4-sintro","title":"间章第一幕：风起鹤归；渊下宫","kind":"chapter","html":"\u003cp\u003e凝光要重建群玉阁。旅行者在寻材途中结识申鹤，一个自幼在山中由仙人抚养、言行与人间格格不入的女子。她曾被至亲舍弃，又受山中生活与红绳约束情绪，因而难以相信自己能在人群中拥有位置。云堇编排的《神女劈观》把她的故事写成戏，但戏文里的神女只身战胜灾祸，现实中的申鹤还要面对活在人间的恐惧。\u003c/p\u003e\n\u003cp\u003e群玉阁升空之时，奥赛尔的妻子跋掣袭向璃月港。凝光、北斗与千岩军按照预先部署迎战，申鹤则以寒冰阻住巨浪，与旅行者一同击退跋掣。庆功宴上，云堇唱起《神女劈观》，又在戏文中添上申鹤与新朋友相识的经历。申鹤也决定尝试留在人间生活。\u003c/p\u003e\n","readingMinutes":1},{"id":"v2.4-s0","title":"重要世界支线：渊下宫","kind":"world","html":"\u003cp\u003e海祇岛下方，旅行者进入与地表隔绝的渊下宫。这里没有真正的太阳，古人造出「大日御舆」照亮黑夜；控制光暗的机关也成为权力工具。被奉为「太阳之子」的儿童统治者，实际上遭大人操纵，长大后又被残酷地处死。曾救下此地居民的蛇神奥罗巴斯，后来带他们迁往海面，海祇岛的历史由此与地下古国相连。\u003c/p\u003e\n\u003cp\u003e旅行者还找到古书《日月前事》。书中记载，「原初之人」与四个影子曾改造世界，后来又有另一股力量降临。渊上称，奥罗巴斯正因读到这段禁忌历史而被判处死刑。旅行者带走了古书，也留下对奥罗巴斯之死和提瓦特起源的疑问。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.4\"\u003e2.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Crane_Returns_on_the_Wind\"\u003e风起鹤归\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Enkanomiya\"\u003e渊下宫\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Before_Sun_and_Moon\"\u003e日月前事\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.5","major":2,"minor":5,"title":"无魔神任务：雷电将军的第二次抉择","chapter":"无主线","sections":[{"id":"v2.5-s0","title":"无魔神任务：雷电将军的第二次抉择","kind":"chapter","html":"\u003cp\u003e影走出一心净土，亲见稻妻人如何在失去之后仍选择向前。她终于意识到，自己把姐姐真珍视的「永恒」理解成了停滞。五百年前，真死于坎瑞亚灾厄；影的哀伤与对磨损的恐惧，使她创造了执行旧规则的将军人偶。如今影要改变方向，人偶却忠于她当初写下的理念，拒绝让步。\u003c/p\u003e\n\u003cp\u003e影与将军在意识空间中持续交战，那里的时间流速异于外界。她坚持新的意志，最终得到将军的认可。真留下的意识随之显现，将神樱之种交给影；种子被她种下，却在过去生根，长成守护稻妻数百年的神樱。姐妹短暂重逢后告别，影决定结束锁国令，亲自面对稻妻的变化。\u003c/p\u003e\n\u003cp\u003e同期「三界路飨祭」再次把旅行者带回渊下宫。侵蚀与深渊的力量威胁地下区域，旅行者借装置净化污染，协助解除笼罩遗迹的黑雾。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.5\"\u003e2.5 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Transient_Dreams\"\u003e须臾百梦\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.6","major":2,"minor":6,"title":"第二章第四幕：回响渊底的安魂曲","chapter":"第二章第四幕","sections":[{"id":"v2.6-sintro","title":"第二章第四幕：回响渊底的安魂曲","kind":"chapter","html":"\u003cp\u003e层岩巨渊深处，旅行者与戴因斯雷布再遇。他们追踪倒悬古城、黑色污泥与深渊教团的机关，发现大量走到生命尽头的丘丘人来到地下，在黑暗中等待死亡。戴因斯雷布说明，坎瑞亚灾厄后的诅咒使许多人变成丘丘人，漫长岁月还会继续磨去他们残存的自我；另一些人则背负不死的诅咒。\u003c/p\u003e\n\u003cp\u003e深渊教团想利用地下装置「净化」诅咒。旅行者起初也盼有一条救赎之路，戴因斯雷布却警告：强行驱除诅咒可能把受难者剩余的生命一起毁掉。昔日坎瑞亚卫队的哈夫丹仍以残破身躯守护同胞；他与戴因斯雷布的相认，让「怪物」一词显得残酷而狭窄。最终，旅行者与戴因斯雷布阻止装置继续伤害受诅咒者，也没能替他们解开诅咒。\u003c/p\u003e\n\u003cp\u003e哈夫丹以身体挡住装置的冲击，为旅行者争取到关闭它的时间。力量散去后，戴因斯雷布看见他恢复人形的幻影，听见了这名旧部最后的询问。哈夫丹终于安息，其他受诅咒者仍留在地下。\u003c/p\u003e\n","readingMinutes":1},{"id":"v2.6-s0","title":"同期世界支线：层岩巨渊","kind":"world","html":"\u003cp\u003e矿工与志琼的调查揭开地下更古老的遗迹、悬浮的奇异晶石和侵蚀地脉的黑泥。旅行者借流明石疏通道路、净化污染，继续向矿区深处调查。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.6\"\u003e2.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Requiem_of_the_Echoing_Depths\"\u003e回响渊底的安魂曲\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Chasm\"\u003e层岩巨渊\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.7","major":2,"minor":7,"title":"间章第二幕：危途疑踪","chapter":"间章第二幕","sections":[{"id":"v2.7-s0","title":"间章第二幕：危途疑踪","kind":"chapter","html":"\u003cp\u003e旅行者在层岩巨渊下方与夜兰、烟绯、荒泷一斗、久岐忍和魈相遇。众人跌入会扭曲道路与记忆的地下空间，出口反复消失，仿佛这座深渊要让每个人面对自己最不愿触碰的往事。魈追索的是五百年前曾在此战斗的夜叉浮舍；夜兰则寻找先辈留下的线索。\u003c/p\u003e\n\u003cp\u003e他们逐渐拼出灾厄时期的战场：坎瑞亚怪物从巨渊涌出，夜叉浮舍与术士伯阳并肩封住缺口。浮舍早被业障与漫长征战夺去记忆，仍留在地下协助封印魔物。直到生命尽头，他才想起自己与其他夜叉的名字。\u003c/p\u003e\n\u003cp\u003e众人借太威仪盘打开退路。魈一度耗尽力量，把生机留给同伴；钟离暗中出手，才使他也从巨渊归来。夜兰查明先祖的经历，魈也终于确认了浮舍的下落。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.7\"\u003e2.7 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Perilous_Trail\"\u003e危途疑踪\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.8","major":2,"minor":8,"title":"无魔神任务：金苹果群岛的幻梦","chapter":"无主线","sections":[{"id":"v2.8-s0","title":"无魔神任务：金苹果群岛的幻梦","kind":"chapter","html":"\u003cp\u003e旅行者与菲谢尔、莫娜、万叶、辛焱等人再赴金苹果群岛。岛屿受到愚人众装置影响，显出与同行者内心相连的幻境：万叶重走家门衰败与离乡之路，辛焱面对对音乐的坚持，菲谢尔直面理想自我与真实自我的距离，莫娜也要承认占星术无法免除人的选择。众人分别走过这些幻梦，装置危机得以平息。\u003c/p\u003e\n\u003cp\u003e旅途末尾，一个陌生的声音通过意识与旅行者交谈。对方一直关注着群岛上的梦境变化，也对旅行者产生了兴趣。旅行者带着这个新疑问，准备前往须弥。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.8\"\u003e2.8 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Summertime_Odyssey\"\u003e远海诗夏游纪\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.0","major":3,"minor":0,"title":"第三章第一至二幕：穿越烟帷与暗林；千朵玫瑰带来的黎明","chapter":"第三章第1至2幕","sections":[{"id":"v3.0-sintro","title":"第三章第一至二幕：穿越烟帷与暗林；千朵玫瑰带来的黎明","kind":"chapter","html":"\u003cp\u003e旅行者踏入须弥雨林，闻到神秘熏香后陷入昏迷，窥见与世界树相连的异象。巡林官提纳里与见习巡林员柯莱将他们带回道成林照料。柯莱幼时因魔鳞病求医，落入愚人众手中，被「博士」手下用于魔神残渣实验；逃到蒙德后得到安柏帮助，赛诺又封印了她体内的残留力量，将她带回须弥。如今她师从提纳里，病情也由他照料。旅行者随后得知，须弥人普遍佩戴虚空终端获取知识，却似乎很少做梦。\u003c/p\u003e\n\u003cp\u003e旅行者进入须弥城，盼见草神小吉祥草王纳西妲，却发现她虽是现任神明，长期不被教令院尊重。花神诞祭前，舞者妮露坚持为草神献舞。节日到了又结束，旅行者却一次次在同一个早晨醒来；熟悉的对话、错位的细节与不断积累的疲惫，证明他们被困在循环里。\u003c/p\u003e\n\u003cp\u003e纳西妲在梦中帮助旅行者保住每次循环的记忆。两人逐步查明，教令院正在用虚空系统收割民众的梦境，城中居民因此反复经历同一天，身体也不断衰弱。旅行者发现妮露就是当前梦境的主人，便让她意识到自己身在梦中。妮露唤出盛开的帕蒂沙兰，跳完献给草神的舞，循环终于瓦解。纳西妲救下濒危的迪娜泽黛，随后借「凯瑟琳」的身体与旅行者在现实中交谈；她本人仍被困在净善宫。\u003c/p\u003e\n","readingMinutes":2},{"id":"v3.0-s0","title":"同期世界支线：森林书","kind":"world","html":"\u003cp\u003e为救受死域侵蚀的拉娜，旅行者与兰那罗们相识，收集惟耶之实所需的回忆，并深入森林对抗「无留陀」。兰罗摩耗尽记忆与力量，化作新的觉王之树；兰拉娜用惟耶之实救醒拉娜，也忘记了与她相处的过去。拉娜获得神之眼，决定与兰拉娜一起旅行，重新积攒属于两人的回忆。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.0\"\u003e3.0 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Aranyaka\"\u003e森林书\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E9%BB%8E%E6%98%8E\"\u003e「黎明」任务正文\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%9F%AF%E8%8E%B1\"\u003e柯莱角色故事与漫画经历\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.1","major":3,"minor":1,"title":"第三章第三至四幕：迷梦与空幻与欺骗；赤土之王与三朝圣者","chapter":"第三章第3至4幕","sections":[{"id":"v3.1-sintro","title":"第三章第三至四幕：迷梦与空幻与欺骗；赤土之王与三朝圣者","kind":"chapter","html":"\u003cp\u003e花神诞祭的梦虽被打破，教令院的计划却没有结束。旅行者与艾尔海森发现，贤者们利用虚空终端操纵舆论、搜索知识，连许多人的判断都被系统牵引。愚人众执行官「博士」多托雷进入须弥，凭借更高层级的虚空权限压制旅行者，并逼迫纳西妲再次退回教令院的禁锢中。\u003c/p\u003e\n\u003cp\u003e线索把众人引向沙漠。赤王遗民长期相信，草神一系夺走了沙漠的繁荣；教令院借这种隔阂，利用被流放的学者与沙漠居民推动秘密研究。旅行者、艾尔海森、赛诺、迪希雅与坎蒂丝在阿如村调查失踪学者，逐渐查明教令院与愚人众正在合作造神。\u003c/p\u003e\n\u003cp\u003e古遗迹中的记录显示，赤王研究禁忌知识，引发灾祸，前代草神曾赶来帮助他遏止污染。拉赫曼等人得知这段历史后，放下对草神的敌意，答应与旅行者合作。众人决定救出纳西妲，阻止教令院的造神计划。\u003c/p\u003e\n","readingMinutes":1},{"id":"v3.1-s0","title":"同期世界支线：黄金梦乡","kind":"world","html":"\u003cp\u003e旅行者随婕德、哲伯莱勒等人走进赤王遗迹，寻找「黄金梦乡」。哲伯莱勒曾是镀金旅团成员，旧日同伙萨梅尔一路追来，企图夺取赤王遗产。最终，哲伯莱勒主动进入黄金梦乡，阻止萨梅尔继续伤害同伴；婕德与旅行者逃出生天，却失去了父亲。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.1\"\u003e3.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Golden_Slumber\"\u003e黄金梦乡\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.2","major":3,"minor":2,"title":"第三章第五幕：虚空鼓动，劫火高扬","chapter":"第三章第五幕","sections":[{"id":"v3.2-s0","title":"第三章第五幕：虚空鼓动，劫火高扬","kind":"chapter","html":"\u003cp\u003e教令院要让散兵取代纳西妲成为新的神明。贤者借花神诞祭等实验收集民众的梦境与知识，博士则提供技术，以雷神之心驱动巨大的机械神躯。\u003c/p\u003e\n\u003cp\u003e旅行者与艾尔海森、赛诺、迪希雅、妮露等人制订各司其职的救援。艾尔海森以被控制的假象潜入教令院，妮露把卫兵引离要地，赛诺追究贤者罪责。纳西妲终于走出净善宫。面对已登上机械神座的散兵，旅行者一次次败下阵来；纳西妲把战斗中的记忆化作可供学习的知识，让旅行者在不断修正中找到胜机，击败新生之神。\u003c/p\u003e\n\u003cp\u003e真正的危机还在世界树中。大慈树王的残留意识告诉纳西妲，五百年前她以自身力量抵御禁忌知识，却也被污染。只要世界仍记得她，污染便不能完全消散。纳西妲必须从世界树中抹去大慈树王的存在；两位草神在最后的相拥中告别。世界随之重写记忆：人们忘记曾有另一位草神，魔鳞病与死域的根本病灶得到清除。\u003cstrong\u003e旅行者作为来自世界之外的人，仍记得那位被遗忘的神。\u003c/strong\u003e\u003c/p\u003e\n\u003cp\u003e博士随后与纳西妲谈判。纳西妲以摧毁雷神之心、可能惊醒天理为筹码，迫使他销毁其他「切片」，再用雷神之心完成交换。博士又以有关世界真相的知识换取草神之心，其中包括提瓦特星空虚假的秘密。纳西妲随后告诉旅行者：愚人众将来自世界之外的存在称为「降临者」，旅行者被列为第四位；血亲却被记录在世界树中，因而未被他们归入其中。血亲为何会留下这些记录，仍需继续追查。\u003c/p\u003e\n","readingMinutes":2}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.2\"\u003e3.2 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%84%8F%E8%AF%86%E4%B9%8B%E8%88%9F%E6%89%80%E8%87%B3%E4%B9%8B%E5%A4%84\"\u003e「意识之舟所至之处」任务正文\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.3","major":3,"minor":3,"title":"间章第三幕：倾落伽蓝","chapter":"间章第三幕","sections":[{"id":"v3.3-s0","title":"间章第三幕：倾落伽蓝","kind":"chapter","html":"\u003cp\u003e散兵战败后留在须弥。旅行者陪他进入世界树，他在那里读到自己作为雷神造物、被遗弃者与愚人众执行官的过去，也读到踏鞴砂悲剧背后的欺骗。他以为自己只给他人带来不幸，便试图从世界树里抹去「散兵」的存在，好让受害者获得另一种人生。\u003c/p\u003e\n\u003cp\u003e旅行者再次查访踏鞴砂，发现死者仍已死去，记录却将他们的遭遇归于其他缘由；人们也忘记了散兵。须弥街头则出现一个与他相貌相同、失去旧日记忆的青年。纳西妲早将散兵的往事写成寓言，避过世界树的改写，如今可以借它让青年了解自己的过去。\u003c/p\u003e\n\u003cp\u003e青年选择取回记忆，在面对过去时获得风元素神之眼。纳西妲留他在须弥，旅行者受托为他起了新的名字。他以流浪者的身份留下，也请旅行者将自己所犯的事告诉受害者的后人。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.3\"\u003e3.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Inversion_of_Genesis\"\u003e倾落伽蓝\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.4","major":3,"minor":4,"title":"无魔神任务：比勒琪丝的哀歌","chapter":"无主线","sections":[{"id":"v3.4-s0","title":"无魔神任务：比勒琪丝的哀歌","kind":"chapter","html":"\u003cp\u003e旅行者再见婕德，随她来到塔尼特部族。主母芭别委派两人深入千壑沙地，寻找永恒绿洲。途中，旅行者与古老的镇灵利露帕尔缔结契约，借她的力量穿过风暴与遗迹。\u003c/p\u003e\n\u003cp\u003e永恒绿洲中的时间停住，留下赤王、花神与前代草神的旧日痕迹。婕德将父母的遗物留在此处。此后，主母芭别露出利用婕德、清除异己的意图，婕德与旅行者联手反击，最终离开塔尼特部族。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.4\"\u003e3.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Dirge_of_Bilqis\"\u003e比勒琪丝的哀歌\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.5","major":3,"minor":5,"title":"第三章第六幕：卡利贝尔","chapter":"第三章第六幕","sections":[{"id":"v3.5-s0","title":"第三章第六幕：卡利贝尔","kind":"chapter","html":"\u003cp\u003e戴因斯雷布在须弥再度现身。凯亚偶然谈及自己的姓氏——亚尔伯里奇——使坎瑞亚的旧影逼近。旅行者随后陷入一段与血亲的记忆相连的经历，见到坎瑞亚贵族克洛达尔·亚尔伯里奇和他的儿子卡利贝尔。父亲是不死的受诅咒者；儿子已变成丘丘人，仍被父亲珍爱。克洛达尔不肯接受儿子只能慢慢失去自我，四处求取能解除诅咒的方法。\u003c/p\u003e\n\u003cp\u003e克洛达尔在神秘晶体前听见「罪人」的声音，随后发现卡利贝尔恢复了神智，便将希望寄托在这股力量上。卡利贝尔后来摘下了面具，旅行者的意识随之中断。记忆的末尾，镜中的倒影显出血亲的面容，旅行者这才确认，自己经历的是血亲当年的见闻。醒来后，戴因斯雷布指出克洛达尔正是深渊教团的创立者。\u003c/p\u003e\n\u003cp\u003e旅行者与戴因斯雷布在屋旁挖出两具遗骨，其中一具属于男性。戴因据此推测，克洛达尔后来或许摆脱了不死诅咒；「罪人」的身份和卡利贝尔此后的遭遇仍然不明。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.5\"\u003e3.5 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Caribert\"\u003e卡利贝尔\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.6","major":3,"minor":6,"title":"无魔神任务：善恶的赫瓦雷纳；智慧主之章·归乡","chapter":"无主线","sections":[{"id":"v3.6-s0","title":"无魔神任务：善恶的赫瓦雷纳；智慧主之章·归乡","kind":"chapter","html":"\u003ch3\u003e善恶的赫瓦雷纳\u003c/h3\u003e\n\u003cp\u003e旅行者与花灵斯露莎走进荼泥黑渊。五百年前，灾厄从此处撕开大地，深渊力量威胁须弥；树、花灵与奉献自身的守护者合力封住裂隙。如今封印松动，旅行者帮助斯露莎完成净化，也读到那些为后人保住土地者留下的记录。\u003c/p\u003e\n\u003cp\u003e斯露莎一度以为自己必须像前辈那样牺牲，后来在与同伴协作中完成仪式，活着回到花海。荼泥黑渊的威胁暂时平息，花灵与矫论团继续守望这片土地。\u003c/p\u003e\n\u003ch3\u003e纳西妲与草之龙\u003c/h3\u003e\n\u003cp\u003e纳西妲与旅行者遇见一些化作蕈兽的元素生命。它们原本生活在草之龙阿佩普体内；阿佩普因吞食赤王与禁忌知识而遭到污染，它们也失去家园。众人找到救治所需的「火种」，却在途中耗损了它。危急时刻，元素生命放弃已有的形体与意识，回归元素，化作新的火种，重燃阿佩普的「绿洲之心」。草之龙得以自愈，体内也重新适宜生命居住。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.6\"\u003e3.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Khvarena_of_Good_and_Evil\"\u003e善恶的赫瓦雷纳\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E8%8B%A5%E5%BF%98%E8%AE%B0%E6%88%91%E4%B8%BA%E4%BD%95%E7%89%A9\"\u003e智慧主之章第二幕「归乡」任务正文：若忘记我为何物\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.7","major":3,"minor":7,"title":"无","chapter":"无主线","sections":[{"id":"v3.7-s0","title":"无","kind":"chapter","html":"\u003cp\u003e旅行者随七圣召唤赛事走访各国，与来自枫丹的记者夏洛蒂相识。赛事结束，寻找血亲的下一站仍是枫丹——水神统治、以审判闻名的国度。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.7\"\u003e3.7 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.8","major":3,"minor":8,"title":"无魔神任务：琉形蜃境","chapter":"无主线","sections":[{"id":"v3.8-s0","title":"无魔神任务：琉形蜃境","kind":"chapter","html":"\u003cp\u003e旅行者与可莉等人来到琉形蜃境，见到由纯水精灵伊迪娅守护的水域幻境。她以水形塑景物和人物，保留过往访客留下的回忆；众人在园区内游历，也结识了这些旧日访客的水形投影。\u003c/p\u003e\n\u003cp\u003e旅行者协助修复蜃境的核心，与可莉等人完成了这次夏日游历，随后准备前往枫丹。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.8\"\u003e3.8 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Veluriyam_Mirage\"\u003e琉形蜃境\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.0","major":4,"minor":0,"title":"第四章第一至二幕：白露与黑潮的序诗；仿若无因飘落的轻雨","chapter":"第四章第1至2幕","sections":[{"id":"v4.0-sintro","title":"第四章第一至二幕：白露与黑潮的序诗；仿若无因飘落的轻雨","kind":"chapter","html":"\u003cp\u003e旅行者来到枫丹，首先看到的是一座把审判当作公共生活中心的国度。水神芙宁娜热爱舞台与喝彩，最高审判官那维莱特则以沉静的姿态主持法庭。传说里的预言在街头流传：海水终将上涨，所有枫丹人会溶解，只剩水神在神座上哭泣。\u003c/p\u003e\n\u003cp\u003e魔术师林尼与妹妹琳妮特接待旅行者。林尼的公开表演发生命案，一名观众也离奇失踪；在法庭上，林尼被指控借魔术杀人。旅行者为他辩护，逐步揭出有人利用舞台机关与「原始胎海之水」犯罪，替他洗清指控。辩护期间，林尼兄妹所属的愚人众组织「壁炉之家」也被揭露，旅行者因两人的隐瞒而生出隔阂。\u003c/p\u003e\n\u003cp\u003e随后，旅行者与刺玫会的娜维娅追查多年女性连环失踪案。娜维娅的父亲卡雷斯当年背负罪名而死，她一直希望查清旧案、为父亲申冤。线索最终指向商人瓦谢：他用原始胎海之水使受害者溶解，妄想找回早已消失的爱人。被害者的意识在水中发声，审判让他的罪行昭于人前，也还了卡雷斯清白。旅行者由此确认，原始胎海之水能使枫丹人溶解。\u003c/p\u003e\n\u003cp\u003e案件结束后，公子也因连环失踪案受审。那维莱特作出无罪判断，「谕示裁定枢机」却宣判有罪。公子试图反抗，被那维莱特制服并送入梅洛彼得堡。两种裁决为何冲突，众人都未能解释。\u003c/p\u003e\n","readingMinutes":2},{"id":"v4.0-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e安眠处与厄里那斯一带的遗迹留下「水仙十字结社」的痕迹。旅行者结识纯水精灵安与美露莘，逐渐接触到旧孤儿院、炼金实验和研究枫丹预言的人们。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.0\"\u003e4.0 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.1","major":4,"minor":1,"title":"第四章第三至四幕：向深水中的晨星；谕示胎动的终焉之刻","chapter":"第四章第3至4幕","sections":[{"id":"v4.1-sintro","title":"第四章第三至四幕：向深水中的晨星；谕示胎动的终焉之刻","kind":"chapter","html":"\u003cp\u003e愚人众执行官公子在枫丹审判中遭「谕示裁定枢机」判有罪，随后从梅洛彼得堡失踪。旅行者主动进入这座海下监狱，寻找他的去向。那里的囚犯有自己的经济与秩序；典狱长莱欧斯利表面上管理牢狱，暗中却为预言准备一艘巨大方舟。监狱最深处封着通往原始胎海的危险缺口。\u003c/p\u003e\n\u003cp\u003e旅行者调查时，胎海之水突然上涌。莱欧斯利与克洛琳德争取时间，那维莱特亲自赶到，暂时稳住缺口。旅行者又在梦中看见公子与胎海中的巨鲸，却仍未找到带他离开监狱的办法。\u003c/p\u003e\n\u003cp\u003e与此同时，愚人众执行官「仆人」阿蕾奇诺与芙宁娜会面。她想确认水神是否真有阻止预言的方案，也关心枫丹孩子的生死；芙宁娜却总用舞台上的姿态遮掩焦虑，无法给出令众人安心的解释。旅行者与那维莱特不得不思考：若灾难已逼近，水神究竟知道多少，又为什么独自承受而不肯说出？\u003c/p\u003e\n","readingMinutes":1},{"id":"v4.1-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e梅洛彼得堡里的「未完成的喜剧」中，旅行者帮助莉诺尔离开监狱，也发现同行的卡特皮拉是一名拥有特殊能力的丘丘人。他与水仙十字结社的关系，将调查引向另一批旧日遗迹。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.1\"\u003e4.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.2","major":4,"minor":2,"title":"第四章第五幕：罪人舞步旋","chapter":"第四章第五幕","sections":[{"id":"v4.2-sintro","title":"第四章第五幕：罪人舞步旋","kind":"chapter","html":"\u003cp\u003e白淞镇遭胎海之水袭击，多名居民溶解。为问出水神应对预言的方案，旅行者与枫丹诸人设局，将芙宁娜带上审判席。芙宁娜无法证明自己拥有神力，也始终不肯透露秘密。她五百年来每天扮演水神，担心任何一次失误都会断送拯救枫丹的机会。\u003c/p\u003e\n\u003cp\u003e那维莱特在「谕示裁定枢机」深处见到真正的水神芙卡洛斯。前代水神厄歌莉娅曾以原始胎海之水让纯水精灵成为人；这在天理看来是「原罪」，预言因此悬在枫丹头顶。芙卡洛斯把自身的神性藏入裁定枢机，让人性的一面——芙宁娜——在世人面前演完五百年的戏。她收集律偿混能，最终用它处决自己，毁去水神神座，把水元素的完整权能还给水龙王那维莱特。\u003c/p\u003e\n\u003cp\u003e预言仍以海水淹没枫丹的形式到来。吞星之鲸从胎海现身，公子曾在水下独自与它缠斗；旅行者和那维莱特最终将它击退。得到完整权能的那维莱特宽恕了枫丹人的「原罪」，使他们真正成为不会因胎海之水而溶解的人。水退后，预言表面上应验，枫丹人却活了下来。\u003c/p\u003e\n\u003cp\u003e芙宁娜终于卸下水神的角色，搬离沫芒宫，开始学习独自生活。那维莱特接过守护枫丹的责任，并将水神之心交给阿蕾奇诺，答谢愚人众在灾难中的援助。\u003c/p\u003e\n","readingMinutes":2},{"id":"v4.2-s0","title":"重要世界支线：水仙十字结社的终局","kind":"world","html":"\u003cp\u003e「水仙的追迹」将安、玛丽安、雅各布与雷内等人留下的线索汇合。雷内曾推演枫丹预言，试图将人们融入集体意识以躲过灾难。旅行者与安、卡特皮拉等人阻止仪式，击败由雷内转变而成的水仙十字。此后，众人各自离开结社留下的遗迹。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.2\"\u003e4.2 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/In_the_Wake_of_Narcissus\"\u003e水仙的追迹\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.3","major":4,"minor":3,"title":"无","chapter":"无主线","sections":[{"id":"v4.3-s0","title":"无","kind":"chapter","html":"\u003cp\u003e枫丹灾厄过后，千灵节重新举行。旅行者与来自稻妻的友人参与「蔷薇与铳枪」映影的拍摄，芙宁娜受邀执导。拍摄期间发生的复仇事件牵出一桩旧案；事件解决后，剧组完成作品，参加千灵映影节。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.3\"\u003e4.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.4","major":4,"minor":4,"title":"无魔神任务：沉玉谷的古老契约","chapter":"无主线","sections":[{"id":"v4.4-s0","title":"无魔神任务：沉玉谷的古老契约","kind":"chapter","html":"\u003cp\u003e旅行者在沉玉谷结识仙人浮锦。旧日纷争使当地水土失调，浮锦又因失去部分力量而难以独力修复，便请旅行者帮助清理翘英庄等地的异常，寻找散落的仙力。\u003c/p\u003e\n\u003cp\u003e旅行者协助浮锦完成投珑仪式，净化沉玉谷水土，并与灵渊交战。旧日纷争平息后，浮锦与灵渊留在山中，谷中居民则继续照料茶田、河流与村落。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.4\"\u003e4.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Chenyu%27s_Blessings_of_Sunken_Jade\"\u003e沉玉祝珑\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.5","major":4,"minor":5,"title":"无","chapter":"无主线","sections":[{"id":"v4.5-s0","title":"无","kind":"chapter","html":"\u003cp\u003e旅行者应丽莎之邀回到蒙德，协助骑士团经营炼金药剂店。枫丹的危机已经平息，关于血亲与深渊教团的调查暂时没有新的进展。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.5\"\u003e4.5 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.6","major":4,"minor":6,"title":"无魔神任务：壁炉之家与雷穆利亚","chapter":"无主线","sections":[{"id":"v4.6-s0","title":"无魔神任务：壁炉之家与雷穆利亚","kind":"chapter","html":"\u003cp\u003e旅行者走近「壁炉之家」。孩子们称阿蕾奇诺为「父亲」，受她庇护，也为愚人众执行任务。上一任院长库嘉维娜曾强迫孩子互相残杀，阿蕾奇诺的挚友克雷薇因此死去。后来，阿蕾奇诺杀死库嘉维娜，接管壁炉之家。面对想离开的孩子，她准备了能焚去相关记忆的药剂，让他们以新的身份生活。她身上的赤月与火焰力量，也留下与坎瑞亚古老血脉有关的线索。\u003c/p\u003e\n\u003cp\u003e佩特莉可镇与海底遗迹引出雷穆利亚。古王雷穆斯曾用乐章与灵露建立王国，希望使臣民摆脱毁灭的命运，王国最终仍然沉没。旅行者与化作猫的奥西同行，唤醒古老的斯库拉，进入黄金宫殿，阻止波爱修斯继续支配众人的灵魂。束缚解除，佩特莉可镇的居民恢复清醒。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.6\"\u003e4.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Canticles_of_Harmony\"\u003e谐律上的咏叙诗\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.7","major":4,"minor":7,"title":"第四章第六幕：睡前故事","chapter":"第四章第六幕","sections":[{"id":"v4.7-s0","title":"第四章第六幕：睡前故事","kind":"chapter","html":"\u003cp\u003e旅行者在维摩庄追查失踪案，与戴因斯雷布会合。村民的记忆出现错乱，线索指向「命运的织机」。卡利贝尔当年死后，意识寄宿在尚未完成的织机中，借它为村民编造记忆，也在其中为自己过上短暂的人类生活。如今织机即将完成，他的意识也将随之消散。\u003c/p\u003e\n\u003cp\u003e卡利贝尔在自己的意识空间里安排双子相见。血亲谈起自己留在提瓦特的缘由，仍请旅行者走完旅途。两人在短暂交谈后告别；卡利贝尔消散，旅行者醒来，失去了这次会面的记忆。后来留下的一张双子合照，成为相会的痕迹。\u003c/p\u003e\n\u003cp\u003e另一边，血亲从戴因斯雷布手中夺得第一台耕地机的「眼睛」，命运的织机至此完成，具备了编织地脉的能力。戴因此前还向旅行者说出坎瑞亚五位「罪人」的名字：他们获得深渊力量，却在灾变时放弃拯救故国，其中「预言家」维瑟弗尼尔正是他的兄长。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.7\"\u003e4.7 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Bedtime_Story\"\u003e睡前故事\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E4%BB%A5%E4%B8%96%E7%95%8C%E4%B9%8B%E6%A0%BC%E7%9A%84%E8%AF%89%E8%AF%B4\"\u003e「以世界之格的诉说」任务正文\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.8","major":4,"minor":8,"title":"无魔神任务：希穆兰卡","chapter":"无主线","sections":[{"id":"v4.8-s0","title":"无魔神任务：希穆兰卡","kind":"chapter","html":"\u003cp\u003e旅行者与妮露、娜维娅、绮良良等人进入希穆兰卡，沿着童话中的预言寻找恶龙。担任「勇者」的流浪者接近杜林后，发现它渴望结交朋友，却因自己的力量给周围造成伤害。众人帮助杜林获得新的形态，使它能与居民接触；希穆兰卡的居民也逐渐接受了这位新朋友。\u003c/p\u003e\n\u003cp\u003e冒险结束后，阿贝多谈到希穆兰卡与现实世界的联系，也提醒众人留意龙脊雪山杜林遗骸的变化。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.8\"\u003e4.8 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Simulanka\"\u003e希穆兰卡\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.0","major":5,"minor":0,"title":"第五章第一至二幕：荣花与炎日之途；黑石湮落白石下","chapter":"第五章第1至2幕","sections":[{"id":"v5.0-sintro","title":"第五章第一至二幕：荣花与炎日之途；黑石湮落白石下","kind":"chapter","html":"\u003cp\u003e旅行者从枫丹入纳塔，最先认识的是回声之子的少女卡齐娜。她几次在盛大的「归火圣夜巡礼」中失利，仍希望取得深入夜神之国、抵抗深渊的资格。纳塔的六个部族与龙伙伴共同生活，战士们通过巡礼选拔参与「夜巡之战」；只要队伍得胜、古名仍被铭记，战死者便有机会借还魂诗复活。\u003c/p\u003e\n\u003cp\u003e卡齐娜终于赢得资格，却在随后的夜巡中阵亡。众人准备以还魂诗迎她归来，火神玛薇卡却找不到她的古名。深渊侵蚀了夜神之国，正在破坏纳塔赖以抵抗它的规则。玛薇卡暂停巡礼，派旅行者、玛拉妮、恰斯卡等人寻找卡齐娜。旅行者能净化一部分深渊力量，令本不可能的救援有了一线希望。\u003c/p\u003e\n\u003cp\u003e愚人众首席执行官「队长」也来到纳塔，认为玛薇卡的计划过于危险，试图夺取火神之心并接手抵抗深渊的行动。二人在圣火前交锋；玛薇卡击退队长，之后为维系圣火耗损了自身力量。旅行者与伙伴进入夜神之国，把卡齐娜带回。她得以复活，众人也确认深渊正在侵蚀古名与还魂诗赖以生效的记忆网络。\u003c/p\u003e\n\u003cp\u003e玛薇卡告诉旅行者，自己的计划需要来自六部族的英雄，还需要一个能在深渊里站立的外乡人。旅行者暂时不能从纳塔神像取得火元素，似乎也在等待那场尚未到来的决战。\u003c/p\u003e\n","readingMinutes":2},{"id":"v5.0-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e纳塔的古名保存英雄事迹，夜神之国承担记忆储存的职责。还魂诗须借这些记录找回战死者；深渊一旦侵蚀古名与记忆，复活就可能失败。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.0\"\u003e5.0 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Flowers_Resplendent_on_the_Sun-Scorched_Sojourn\"\u003e荣花与炎日之途\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Black_Stone_Under_a_White_Stone\"\u003e黑石湮落白石下\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.1","major":5,"minor":1,"title":"第五章第三至四幕：镜与谜烟的彼方；命定将焚的虹光","chapter":"第五章第3至4幕","sections":[{"id":"v5.1-s0","title":"第五章第三至四幕：镜与谜烟的彼方；命定将焚的虹光","kind":"chapter","html":"\u003cp\u003e旅行者协助希诺宁寻找为外乡人锻造古名的办法，又与茜特菈莉追查烟谜主青年欧洛伦为何救走队长。队长经历过五百年前的坎瑞亚灾厄，不愿再看见一个国家被深渊毁灭。他担心玛薇卡的计划来不及完成，试图借古代装置重塑夜神之国的地脉，却会因此耗尽守护此地的夜神。\u003c/p\u003e\n\u003cp\u003e欧洛伦在装置危机中抗拒侵入自己灵魂的旧日亡魂，继承「奉献」的古名。夜神之国的主人向众人现身：她曾属于早于如今仙灵形态的「天使」一族，长久维系纳塔特殊的记忆网络。玛薇卡拒绝为眼前安全把她耗尽。队长虽仍不完全认同，也决定先与纳塔结盟，共抗逼近的深渊。\u003c/p\u003e\n\u003cp\u003e灾难很快真正降临。深渊同时袭击多个部族、道路和村落，旅行者随各地求援不断奔走。有人赶上救援，有人来不及；恰斯卡失去妹妹，纳塔人也不得不统计一座座村落的死伤。玛薇卡与六英雄汇聚力量，向蔓延的黑暗挥出足以撕开天空的一击，暂时止住全面入侵。天空裂隙中显露的异象，让「提瓦特的天空」也成为无法忽视的疑问。\u003c/p\u003e\n\u003cp\u003e纳塔赢下的是喘息时间。玛薇卡若要调用主宰死亡的力量彻底结束战争，自己也将被索取代价。旅人与盟友知道了这个风险，仍选择为下一次、也是最后一次深入夜神之国做准备。\u003c/p\u003e\n","readingMinutes":2}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.1\"\u003e5.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Beyond_the_Smoke_and_Mirrors\"\u003e镜与谜烟的彼方\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Rainbow_Destined_to_Burn\"\u003e命定将焚的虹光\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.2","major":5,"minor":2,"title":"第五章间幕：万火归一","chapter":"第五章间幕","sections":[{"id":"v5.2-sintro","title":"第五章间幕：万火归一","kind":"chapter","html":"\u003cp\u003e大战之后，花羽会受创尤重。旅行者与伊安珊探望幸存战士：有人在噩梦中仍看见已死的龙伙伴，有人把亲友认作深渊怪物。众人协助他们接受治疗、告别死去的伙伴。队长提供曾由部下研究的药物，救下一名受深渊侵蚀严重的战士。\u003c/p\u003e\n\u003cp\u003e希诺宁仍在为旅行者锻造古名。朋友们聚在「巡礼之证」前，讲述旅行者在纳塔的所作所为；玛拉妮、卡齐娜、基尼奇、茜特菈莉、欧洛伦与恰斯卡的见证，将一个外乡人的事迹写进夜神之国可以接纳的历史里。古名还未完成，但这份共同记忆已经让最后的决战有了根基。\u003c/p\u003e\n","readingMinutes":1},{"id":"v5.2-s0","title":"同期世界支线","kind":"world","html":"\u003cp\u003e奥奇卡纳塔遗迹保留着龙族城市与秘密源装置。旅行者深入其中，接触到龙族统治者留下的记录，也发现古老设施至今仍在运转。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.2\"\u003e5.2 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/All_Fires_Fuel_the_Flame\"\u003e万火归一\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.3","major":5,"minor":3,"title":"第五章第五幕：炽烈的还魂诗","chapter":"第五章第五幕","sections":[{"id":"v5.3-s0","title":"第五章第五幕：炽烈的还魂诗","kind":"chapter","html":"\u003cp\u003e决战前夜，纳塔人设宴送行。玛薇卡谈起五百年前的家人，也为可能无法归来作好准备。希诺宁终于铸成旅行者的古名 \u003cstrong\u003e「图玛伊尼」——希望\u003c/strong\u003e，将这位外乡人在纳塔的事迹写入夜神之国的记忆，使他也能得到还魂诗的庇护。\u003c/p\u003e\n\u003cp\u003e玛薇卡寻找深渊的核心，旅行者沿另一条路前进。途中，牺牲者的灵魂为他们指路，部族战士与古代英雄也赶来相助。两人汇合后，迎战化作火龙王形貌的深渊魔物。旅行者在战斗中获得火元素之力，与玛薇卡一同击败对手，解除纳塔地脉中的危机。\u003c/p\u003e\n\u003cp\u003e胜利之后，死之执政仍要收取玛薇卡使用其力量的代价。队长站了出来。他身负坎瑞亚的不死诅咒，五百年来一直携带同袍的亡魂。他选择与夜神之国的主人合一，使两份力量相互制衡，为亡魂留下安息之所，也替玛薇卡偿付了代价。\u003c/p\u003e\n\u003cp\u003e旅行者从玛薇卡那里得知，博士正在至冬边境的挪德卡莱研究天空碎片与古月遗物。众人在圣火竞技场为队长告别，旅行者开始准备下一段旅程。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Incandescent_Ode_of_Resurrection\"\u003e炽烈的还魂诗任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.3\"\u003e5.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.4","major":5,"minor":4,"title":"无","chapter":"无主线","sections":[{"id":"v5.4-s0","title":"无","kind":"chapter","html":"\u003cp\u003e纳塔大战后，旅行者回到稻妻参加三川花祭，与故友重逢。队长与亡魂已在夜神之国安息，旅行者仍留意着玛薇卡提到的消息：博士正在挪德卡莱研究天空碎片与古月遗物。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.4\"\u003e5.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.5","major":5,"minor":5,"title":"无魔神任务：古圣山的余烬","chapter":"无主线","sections":[{"id":"v5.5-s0","title":"无魔神任务：古圣山的余烬","kind":"chapter","html":"\u003cp\u003e旅行者循遗迹与古龙伙伴的足迹深入圣山。岩壁、装置和残存记录讲述更古老的纳塔：龙曾建立高度发达的文明，人类后来在战争与联盟中取得今日的生存空间。火、源火与秘密源技术既能守护生命，也曾被统治者用来塑造服从。如今各部族竞赛的热闹，与山下仍在沉睡的旧日王权形成鲜明反差。\u003c/p\u003e\n\u003cp\u003e旅行者与龙伙伴继续追查圣山的秘密，接近龙族遗留的圣火与古老试炼。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.5\"\u003e5.5 版本新增地区与世界任务\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.6","major":5,"minor":6,"title":"间章第四幕：悖理","chapter":"间章第四幕","sections":[{"id":"v5.6-s0","title":"间章第四幕：悖理","kind":"chapter","html":"\u003cp\u003e旅行者回到蒙德过风花节，却发现城里有人行为反常，阿贝多又被控杀人。审判的证人与证据像是指向他，旅行者却记得雪山曾有与他相同容貌的造物。骑士团借审判诱出潜伏者，揭露杜林遗骸中滋生的生命会模仿人、吞噬人，并把怀疑引向阿贝多。怪物向蒙德发动袭击，骑士团与城中友人合力守住城门。\u003c/p\u003e\n\u003cp\u003e龙脊雪山的杜林即将复苏。阿贝多向魔女会寻求炼金材料，准备清除旧龙躯中的恶意，再将希穆兰卡的小杜林与之结合。温迪、艾莉丝等人协助完成仪式，小杜林获得人形，蒙德暂时摆脱巨龙复苏的威胁。\u003c/p\u003e\n\u003cp\u003e阿贝多还透露，创造他的莱茵多特与「生之执政」纳贝里士发生了融合。旅行者由此得知，坎瑞亚的「黄金」如今也与天空岛的四影有关。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Paralogism\"\u003e悖理任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.6\"\u003e5.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.7","major":5,"minor":7,"title":"第五章第六幕：你存在的时空","chapter":"第五章第六幕","sections":[{"id":"v5.7-s0","title":"第五章第六幕：你存在的时空","kind":"chapter","html":"\u003cp\u003e旅行者在纳塔捡到血亲的飞船休眠舱钥匙，自己的那一把仍留在身上。随后遇见的少女蒂莱尔，正寻找能阻止末日的「救世主」，描述与旅行者的血亲相符。少女与众人看见的魔物并不相同，仿佛身处两个世界。戴因斯雷布认出，「救世主」是坎瑞亚人在灾变前对血亲的称呼。\u003c/p\u003e\n\u003cp\u003e深渊教团大举进攻纳塔，引来戴因追击。旧日剑术老师哈登借叙旧唤起他对故国的回忆，供「命运的织机」读取。五百年的磨损已使教团遗民记忆残缺，戴因保留得更完整的记忆，补齐了编织坎瑞亚地脉的原料。纳塔战事正是为此布下的诱饵。\u003c/p\u003e\n\u003cp\u003e回到山洞，旅行者牵住蒂莱尔的手，眼前骤然出现赤红天空与燃烧的大地：少女仍身在五百年前的坎瑞亚灾变中。她想带一件见过旅行者的凭证，去向「救世主」求援。旅行者取出自己的钥匙，正要决定是否交给她时，少女所在的时间停滞，血亲现身。\u003c/p\u003e\n\u003cp\u003e血亲记得，五百年前蒂莱尔曾带着这把钥匙找来，一面请求拯救坎瑞亚，一面带来旅行者的消息。血亲最终选择先去寻找家人，找到的却是尚未苏醒、身上仍带原有钥匙的旅行者。来自未来的同一把钥匙与原钥匙同时存在，形成了时间回环。少女盼望借求援挽救故国，她带去的消息反而让「救世主」选择带家人离开。血亲怀疑这场跨越五百年的相遇受到了时之执政伊斯塔露的影响。\u003c/p\u003e\n\u003cp\u003e血亲也说明了织机的进展：经夜神许可，以因提瓦特花为基底，展开五百年前的坎瑞亚空间，叠加于当下纳塔；旅行者因此能与蒂莱尔相遇。教团遗民与戴因的记忆共同织成「新世界的经纬图」，但夜神之国无法承载新地脉，坎瑞亚尚未复国，仍须寻找容纳它的空间。血亲希望以一个完整的世界，取得与天理对话的资格。\u003c/p\u003e\n\u003cp\u003e旅行者试图改变少女的命运，血亲却仍要保住当年与家人重逢的机会，将那片空间收入经纬图，带着蒂莱尔一同消失。旅行者独自回到现实；在派蒙眼里，旅行者只短暂消失了一会儿。教团撤离纳塔，双子再次分开。\u003c/p\u003e\n","readingMinutes":2}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Space_and_Time_for_You\"\u003e你存在的时空任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E4%BD%A0%E6%89%80%E4%B8%8D%E5%9C%A8%E7%9A%84%E6%97%B6%E7%A9%BA\"\u003e「你所不在的时空」任务正文：钥匙回环与新世界的经纬图\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.7\"\u003e5.7 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.8","major":5,"minor":8,"title":"空月之歌·序奏：归途","chapter":"空月之歌序奏","sections":[{"id":"v5.8-s0","title":"空月之歌·序奏：归途","kind":"chapter","html":"\u003cp\u003e纳塔海边出现一名失忆的机械少女。她记得要找到旅行者与派蒙，却记不起自己为何而来；来自挪德卡莱的商队叫她伊涅芙。她的身体混合了枫丹机关、纳塔秘密源技术与其他地区的材料，而她护送的密匣，似乎专为旅行者准备。\u003c/p\u003e\n\u003cp\u003e伊涅芙在纳塔古龙遗迹中遭到旧日意识争夺，旅行者与恰斯卡、希诺宁、茜特菈莉等人协助她摆脱控制。她逐渐恢复行动能力，也与一路帮助自己的人建立起新的联系。愚人众同时在追索遗迹技术。\u003c/p\u003e\n\u003cp\u003e密匣里装着西风骑士团大团长法尔伽的信。他在挪德卡莱，提醒旅行者那里聚集着愚人众、深渊教团与彼此紧张的地方势力，并约他们在当地见面。另有消息提到，博士正在研究古月遗物，甚至打算把月亮拖向地面。旅行者决定先赴挪德卡莱，与法尔伽会合。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Journey_Home\"\u003e归途任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.8\"\u003e5.8 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.0","major":6,"minor":0,"title":"空月之歌第一、二幕：雪浪与苍林之舞；尘与灯的挽歌","chapter":"空月之歌第1至2幕","sections":[{"id":"v6.0-s0","title":"第一幕：雪浪与苍林之舞","kind":"chapter","html":"\u003cp\u003e旅行者与派蒙带着伊涅芙来到挪德卡莱的那夏镇。他们寻访失散已久的星间飞船，也想找到西风骑士团大团长法尔伽。愚人众、商会、执灯人与信奉月神的霜月之子在这里各有势力。空气中流动的「月矩力」使旅行者感到熟悉，仿佛与双子最初降落于此的往事有关。\u003c/p\u003e\n\u003cp\u003e霜月之子的菈乌玛讲起古老的三月传说。夜间散步时，月灵努昂诺塔替旅行者打开岩壁暗门，让旅行者在花海中初见哥伦比娅。她曾是愚人众的「少女」，如今已脱离他们，仍被月光与故乡的渴望牵引。\u003c/p\u003e\n\u003cp\u003e离开花海后，旅行者一度与「血亲」并肩行动，重逢的希望很快化为陷阱：那是「狂猎」借熟悉面容作出的拟态。爱诺、菲林斯和愚人众执行官「木偶」桑多涅也各自追索月之遗物；当名为「月髓」的东西现身，几方同盟随时可能散开。菈乌玛坦言族人所受的苦难，以及她的血为何与月髓有关；旅行者因此暂把月髓藏入自己体内，避免它立即落入任何一方手中。\u003c/p\u003e\n","readingMinutes":1},{"id":"v6.0-s1","title":"第二幕：尘与灯的挽歌","kind":"chapter","html":"\u003cp\u003e线索把众人引向坎瑞亚旧灾。月髓被认为是已毁之月「艾莉亚」的残骸；追逐它的狂猎则与坎瑞亚五位「罪人」之一雷利尔有关。雷利尔能以他人形貌现身，搜集散落的自身遗骸，试图恢复失去的肉身。守灯人菲林斯也承认自己的来历异于常人；他选择帮助活着的人，而灯中封存着雷利尔心脏的一片碎屑。\u003c/p\u003e\n\u003cp\u003e雷利尔诱导爱诺的月矩力大炮向自己开火，借受污染的力量重铸躯体。桑多涅的干预未能拦住他，众人陷入险境，哥伦比娅以霜月之力救下同伴。雷利尔离开后，法尔伽循踪追去。\u003c/p\u003e\n","readingMinutes":1},{"id":"v6.0-s2","title":"此刻悬而未决","kind":"question","html":"\u003cp\u003e旅行者的飞船究竟落在何处？哥伦比娅为何与月髓相连？雷利尔要用恢复的身体做什么？法尔伽能否追上他？\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Dance_of_Snowy_Tides_and_Hoarfrost_Groves\"\u003e第一幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Elegy_of_Dust_and_Lamplight\"\u003e第二幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%A9%BA%E6%9C%88%E4%B9%8B%E6%AD%8C\"\u003e空月之歌中文幕名与任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E4%BA%8E%E6%9C%88%E5%85%89%E4%B8%8B%E9%87%8D%E9%80%A2\"\u003e「于月光下重逢」任务正文：努昂诺塔的引路\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.1","major":6,"minor":1,"title":"空月之歌第三、四幕：不存在的国土；回望湮灭的月光","chapter":"空月之歌第3至4幕","sections":[{"id":"v6.1-s0","title":"第三幕：不存在的国土","kind":"chapter","html":"\u003cp\u003e雷利尔重获部分身体后，矛头指向哥伦比娅。法尔伽赶来援救，旅行者等人则寻找另一枚虹月月髓，希望为她争取对抗狂猎的力量。月髓藏在一处与坎瑞亚旧史相连的秘境里，普通人无法轻易踏入。\u003c/p\u003e\n\u003cp\u003e愚人众执行官「仆人」阿蕾奇诺以赤月王朝后裔的身份相助。她动用自身力量打开道路，与旅行者等人取得月髓，手也因此受到深渊侵蚀。\u003c/p\u003e\n","readingMinutes":1},{"id":"v6.1-s1","title":"第四幕：回望湮灭的月光","kind":"chapter","html":"\u003cp\u003e奈芙尔追查坎瑞亚宫廷的旧档，拼出雷利尔成为「罪人」之前的人生。昔日的坎瑞亚王伊尔明曾命他清除赤月王朝的后裔；名单里竟有他的未婚妻索琳蒂丝。他曾与戴因斯雷布、莱茵多特等人试图救下维瑟弗尼尔，索琳蒂丝却坠入深渊。王命、故国与所爱之人一同崩塌，雷利尔终于接受深渊的力量。今日的狂猎既是灾厄的追兵，也是一名旧时代幸存者扭曲的执念。\u003c/p\u003e\n\u003cp\u003e奈芙尔用棋盒暂困雷利尔，给众人布置最后一搏的时间。阿贝多与已拥有人形的杜林帮助哥伦比娅承受月之力量；戴因斯雷布维系通往月的门扉。众人合力将雷利尔逐出提瓦特，才使挪德卡莱免于眼前的追猎。胜利没有抹去过去的伤：阿蕾奇诺的手、杜林对自身出身的疑虑，以及哥伦比娅与月之间越来越难割断的联系，都仍在他们身上。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Nation_That_Doesn%27t_Exist\"\u003e第三幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/An_Elegy_for_Faded_Moonlight\"\u003e第四幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%A9%BA%E6%9C%88%E4%B9%8B%E6%AD%8C\"\u003e空月之歌中文幕名与任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.2","major":6,"minor":2,"title":"空月之歌第五、六幕：终北的夜行诗；散于晨雾的月芒","chapter":"空月之歌第5至6幕","sections":[{"id":"v6.2-s0","title":"第五幕：终北的夜行诗","kind":"chapter","html":"\u003cp\u003e雷利尔之乱过去约两个月，挪德卡莱准备迎来「祈月之夜」。哥伦比娅告诉旅行者：那夜月矩力最盛，她必须借机返回月亮；继续留在提瓦特，她会逐渐消失。菈乌玛虽不舍，也无法以族人的祈愿强留她。旅行者与朋友们于是筹备一场告别的节庆，让她带着这里的记忆离开。\u003c/p\u003e\n\u003cp\u003e古老亥珀波瑞亚人的虚影却在各地浮现，甚至出现旅行者那艘星间飞船的幻影。法尔伽、奈芙尔、阿贝多和杜林等人分头调查。旅行者可以与虚影交谈，仍无法阻止那些人重演死亡。菲林斯认出自己经历过的旧日灾祸；杜林也在调查中接触自身的深渊力量，尝试学习控制它。\u003c/p\u003e\n\u003cp\u003e随后哥伦比娅从银月之庭消失。艾莉丝亲自现身，指出三月的力量汇聚挪德卡莱，提瓦特边界因此不稳。更迫切的是，哥伦比娅并未真正离开：她在失去力量、身份和归属后，正被世界排斥，连形体也难以维持。仅有月髓不足以送她回家。众人必须找到能使她继续存在的「真名」，还要打通通往月亮的路。尼可带来亥珀波瑞亚遗迹的线索；旅行者、菈乌玛与阿蕾奇诺承担进入遗迹所需的月矩力试炼。哥伦比娅的意识一直在旁边目睹他们寻找，却已虚弱到无法随行。\u003c/p\u003e\n","readingMinutes":2},{"id":"v6.2-s1","title":"第六幕：散于晨雾的月芒","kind":"chapter","html":"\u003cp\u003e在尼可开启的古老虚影中，众人读到三月女神与提瓦特的断裂史。按尼可所述，龙王尼伯龙根曾使三月升起；后来他以深渊之力与天理再战，将月亮改为兵器，三月女神也因分歧和战争遭囚。天理击碎两月、把另一月逐出天外。壁画与口述让哥伦比娅为何难以在此世长存，有了更沉重的解释。\u003c/p\u003e\n\u003cp\u003e然而走遍遗迹，谁也找不到一份早已写下的「真名」。尼可反问众人：若过去从未有人为哥伦比娅命名，何不在今日由她认同的人呼唤她？旅行者、菈乌玛与阿蕾奇诺都呼唤「哥伦比娅」——那个曾是愚人众代号，如今却盛满共同回忆的名字。即将消散的少女听见了他们。她接受这个名字，为自己添上「希珀塞莱尼娅」，意为诞生于月下，也意为在这个世界获得新生。\u003c/p\u003e\n\u003cp\u003e祈月之夜终于成为一场真正的告别。哥伦比娅与朋友们同游那夏镇，在最热闹的灯火之后走向通月之门。门却被「博士」多托雷预先布下的伪月劫持。他利用虚影中堆积的「变数」与月之知识，让术法把哥伦比娅送到自己身边；三月之力落入他手中，周围的时间几乎停滞。旅行者独自迎战而不敌。哥伦比娅为破坏他的掌控，主动跃入未知的「月亮倒影」。多托雷失去完整力量而撤退，她却也没有回到原本的月亮。\u003c/p\u003e\n\u003cp\u003e众人从震惊中重新站起。流浪者揭穿伪月如何误导传送门，阿蕾奇诺、法尔伽、菈乌玛、奈芙尔、桑多涅与魔女会各担一方：寻找哥伦比娅，查清博士的下一步，并守护挪德卡莱。旅行者望向夜空，节日留下的糖与贺卡仍在手中；他们刚为一人找到名字，如今必须再把她找回来。\u003c/p\u003e\n","readingMinutes":2}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Nocturne_of_the_Far_North\"\u003e第五幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%95%A3%E4%BA%8E%E6%99%A8%E9%9B%BE%E7%9A%84%E6%9C%88%E8%8A%92\"\u003e第六幕中文任务\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E5%90%8D%E4%BA%8E%E4%BD%95%E5%A4%84%EF%BC%9F\"\u003e名于何处？\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E5%9B%9E%E5%88%B0%E6%9C%88%E4%BA%AE%E4%B8%8A%E5%8E%BB\"\u003e回到月亮上去\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.3","major":6,"minor":3,"title":"空月之歌第七、八幕：如果在冬夜，一个旅人；真实之月","chapter":"空月之歌第7至8幕","sections":[{"id":"v6.3-s0","title":"第七幕：如果在冬夜，一个旅人","kind":"chapter","html":"\u003cp\u003e哥伦比娅失踪后，阿蕾奇诺与桑多涅先行攻入博士的北方研究所。旅行者、法尔伽和菈乌玛等人循迹赶到，见到被焚毁的兵器、逃散的愚人众，以及博士长期制造人工月髓的证据。博士早料到众人会来。他以人工月髓修复战伤，连旅行者与阿蕾奇诺联手也无法将他击败；随后，他把同伴们送离，只将旅行者囚入自己的异空间。\u003c/p\u003e\n\u003cp\u003e博士想招揽这位来自世界之外的「降临者」。他声称能终结旅行者漫长的寻亲之路，质疑众人为何要遵从神定的命运。旅行者明知他话里藏着诱饵，仍留意其中有关世界规则的情报，等待脱身的机会。博士则在挪德卡莱制造能量界域，进行把人的意识移入动物身体等实验，以近乎残酷的方式试探其新权能。\u003c/p\u003e\n\u003cp\u003e地面上的盟友没有坐等。桑多涅发现博士在同行者身上埋下诅咒；法尔伽和霜月之子、执灯人疏散居民，阿蕾奇诺及愚人众把北方民众送往至冬，南方则向纳塔撤离。公子带来冰之女皇的授权：若博士已危及一切，阿蕾奇诺与桑多涅可以对他下杀手。杜林向蒙德求援，多莉向须弥送信，阿贝多、流浪者与魔女会研究那些界域。昔日立场相异的人，此刻都把保住一方土地放在首位。\u003c/p\u003e\n\u003cp\u003e月亮倒影中的哥伦比娅仍活着，却被困在逆流的时间里。她尝试向过去留下线索，并以部分灵魂创造月灵努昂诺塔，将它送去陪伴过去的旅行者。当初替旅行者打开岩壁暗门的月灵，正是她留在过去的帮助。如今，奈芙尔也借努昂诺塔找到了与她联络的线索。\u003c/p\u003e\n","readingMinutes":2},{"id":"v6.3-s1","title":"第八幕：真实之月","kind":"chapter","html":"\u003cp\u003e流浪者借阿贝多的炼金信号闯入博士的囚笼，救出旅行者。他暂放下亲手复仇的机会，因为众人的计划更需要旅行者活着。桑多涅则取枫丹的研究与月之知识推演「世界公式」，寻找把逆流中的哥伦比娅拉回此刻的方法。流浪者自愿以自己的核心接入地脉替她运算，明知意识可能被重置甚至失散。\u003c/p\u003e\n\u003cp\u003e哥伦比娅在时间尽头遇到雷利尔与索琳蒂丝残存的灵魂，也发现博士早曾利用雷利尔复生来布置今日的局。再往前，她见到被囚禁的三月女神。她们知道自己的结局，仍把权能交给后来者。哥伦比娅把身体化为散布在过去挪德卡莱的月光，灵魂寄于努昂诺塔，等待朋友们在未来重聚这三部分。奈芙尔曾准备以双目为代价窥见这段遥远往事；哥伦比娅的安排使她免受此伤。\u003c/p\u003e\n\u003cp\u003e决战时，博士以伪月之主的姿态撕开天空，在云上隔绝旅行者、菲林斯、菈乌玛和奈芙尔。他以为桑多涅的公式还差最后一步，便向旅行者施以致命一击。桑多涅替旅行者挡下，身体遭重创，仍把真实的计算留在随她行动的巨型机仆普隆尼亚体内。博士误以为她死去便能截断公式，却没看见她让自己成为了诱饵。\u003c/p\u003e\n\u003cp\u003e阿蕾奇诺、法尔伽与尼可将真正的霜月牵引到提瓦特，穿过伪天的裂口；流浪者的核心完成余下运算。散在大地的月光、努昂诺塔携带的灵魂与三月权能汇合，哥伦比娅从月下归来。她与旅行者夺回月髓，救出被隔绝的同伴，合力击碎博士的人工月髓。博士的形体随之消散，哥伦比娅赶到桑多涅身旁，将受创的她抱在怀中。\u003c/p\u003e\n\u003cp\u003e挪德卡莱各方结盟共治，霜月留在提瓦特。阿蕾奇诺依桑多涅的嘱托，带她与普隆尼亚的核心回枫丹处理后事；流浪者返回须弥。哥伦比娅则带旅行者登上霜月，找到当年双子乘坐的飞船。飞行记录显示，飞船曾在数千年前路过提瓦特，之后又返回并在挪德卡莱坠落。旅行者仍不知为何折返，却第一次站在当年离开与归来的器物前，坦承这片世界也已成为自己的家。哥伦比娅把部分月之恩泽还给大地，也松开了旅行者使用元素时受到的一些限制。\u003c/p\u003e\n","readingMinutes":2},{"id":"v6.3-s2","title":"此刻悬而未决","kind":"question","html":"\u003cp\u003e飞船为何返回？「博士」在这一战后的命运是否已经彻底定下？冰之女皇与至冬诸执行官各自要怎样使用神之心？旅行者带着这些仍未揭晓的问题，继续向北。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Traveler_on_a_Winter%27s_Night\"\u003e第七幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/True_Moon\"\u003e第八幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E5%A6%82%E6%9E%9C%E5%9C%A8%E5%86%AC%E5%A4%9C%EF%BC%8C%E4%B8%80%E4%B8%AA%E6%97%85%E4%BA%BA\"\u003e第七幕中文任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%9C%9F%E5%AE%9E%E4%B9%8B%E6%9C%88\"\u003e第八幕中文任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%A9%BA%E6%9C%88%E5%BD%92%E4%B9%A1\"\u003e「空月归乡」任务正文：桑多涅与普隆尼亚的核心\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.4","major":6,"minor":4,"title":"无新增魔神任务","chapter":"无主线","sections":[{"id":"v6.4-s0","title":"无新增魔神任务","kind":"chapter","html":"\u003cp\u003e伪月之战过后，挪德卡莱各方开始共同治理当地，霜月也已归来。旅行者与法尔伽等人继续处理远征留下的事务，随后回到蒙德，与归来的骑士和故友重聚。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/Luna_V\"\u003e6.4／月之五版本新增任务\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.5","major":6,"minor":5,"title":"无新增魔神任务：山中好长日与空之神殿","chapter":"无主线","sections":[{"id":"v6.5-s0","title":"重要世界支线：山中好长日","kind":"world","html":"\u003cp\u003e旅行者在山中一处废弃疗养院遇到寻找姐姐的少女。姐姐似乎已死，墓碑甚至让二人的相貌重叠；然而一名自称守望者的巨大神殿造物突然现身，将他们引向高悬于常世之外的空之神殿。那里由掌管空间的神明阿斯莫代创造。造主离去后，另一守望者梅兰塔把神殿变作囚笼，居民遭追猎，有的被困在画与书页里，有的化作沙尘。\u003c/p\u003e\n\u003cp\u003e少女一路拾回姐姐留下的画、书信与饰物。她逐渐知道，姐姐曾在神殿中与众人相识，也曾试图终止梅兰塔的统治。通往神殿核心的道路要求献出全部记忆；当年姐姐已经付过这笔代价，如今妹妹仍决定踏上同一条路。旅行者击败梅兰塔。那守望者终于承认：造主不在，造物早有选择去留的自由；他以「纠正」他人为名施暴，实则害怕失去造主的认可。神殿重获自由，少女却在回到地面时忘了自己所经历的一切。旅行者陪她重新开始，也保留姐姐可能仍在人世的希望。\u003c/p\u003e\n\u003cp\u003e神殿中的线索指向最初封印双子的陌生神明——\u003cstrong\u003e阿斯莫代，空间之执政\u003c/strong\u003e。她为何离开神殿，又为何阻止双子离开提瓦特，仍待查明。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/Luna_VI\"\u003e6.5／月之六版本新增区域与任务\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Long_Day_in_the_Mountains\"\u003e山中好长日任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.6","major":6,"minor":6,"title":"空月之歌第九、十幕：身土坏空，五蕴识转；虚空劫灰往世书","chapter":"空月之歌第9至10幕","sections":[{"id":"v6.6-s0","title":"第九幕：身土坏空，五蕴识转","kind":"chapter","html":"\u003cp\u003e柯莱写信求援。她梦见须弥城里人人身份错乱，连提纳里也不认识她；尼可的声音警告她，梦中的灾难即将发生。旅行者从挪德卡莱赶来时，世界树已无法正常处理地脉信息，记忆与认知随之失序。纳西妲以自身承接堵塞的信息，耗尽力量后昏迷，教令院与巡林官开始撤离民众。\u003c/p\u003e\n\u003cp\u003e旅行者想到草龙阿佩普曾受纳西妲救助，便带她前往沙漠求援。阿佩普把生命力量分给她，并指出世界树本是古龙时代之物，后来被天理接管与改造。纳西妲短暂醒来，交给旅行者一枚花形钥匙，留下只准他们独自保管的线索。另一边，贤者们试图重启曾由草神之心驱动的「虚空」系统，却必须寻找新能量，也必须阻止沙漠中突然兴起的镇灵风暴。\u003c/p\u003e\n\u003cp\u003e风暴把旅行者引回居尔城。他们与昔日同伴婕德重逢，唤醒镇灵利露帕尔，由她平息镇灵暴乱。尼可和奈芙尔也在封锁前进入须弥；尼可揭示，柯莱体内当年被博士植入的神之残骸，来自花神娜布·玛莉卡塔，这才使她能以花神的祈词安抚镇灵。\u003c/p\u003e\n\u003cp\u003e众人重启赤王留下的「阿如」装置。古代七柱同意协助，让沙漠的古技术承担须弥新的守护。阿如短暂敞开，婕德得与父亲的灵魂再见一面。须弥诸人此时尚未找出幕后者，但已经把雨林、沙漠与古老的敌意暂且放下，准备共同抵御下一波灾难。\u003c/p\u003e\n","readingMinutes":2},{"id":"v6.6-s1","title":"第十幕：虚空劫灰往世书","kind":"chapter","html":"\u003cp\u003e须弥城长出一株异常巨树，博士的实验在那里继续。他曾将剩余灵魂分成两半，一半前往挪德卡莱，一半藏于北国银行。挪德卡莱一战后，死去的那部分灵魂流入地脉，潘塔罗涅再依约送入另一半，使其重新合一。博士由此进入世界树，避开纳西妲的外部防线。\u003c/p\u003e\n\u003cp\u003e纳西妲制定大胆的计划：以重新启用的虚空系统让世界树停摆，再将信息转存至改造后的阿如。所需的火元素神之心由玛薇卡交出。为免计划被地脉记录、被博士提前读到，纳西妲借旅行者这个世界树无法记录的人与纳塔一侧沟通。艾尔海森、卡维和贤者改造阿如，赛诺、迪希雅、坎蒂丝、婕德等人从正面攻城；旅行者与流浪者则沿巨树潜入，直抵世界树深处。\u003c/p\u003e\n\u003cp\u003e博士认出流浪者被世界树抹去的旧身份，借其悔恨扰乱两人。流浪者与旅行者继续掩护纳西妲转移信息。纳西妲在世界树中见到时、生、死三位执政的意志，提出焚毁已受污染的世界树，以阿如接管信息。得到许可后，她点燃火神之心。烈焰沿根系蔓延，博士企图拖旅行者同坠，却被那些憎恨原体的切片缠住。旅行者、流浪者与纳西妲终于脱身。\u003c/p\u003e\n\u003cp\u003e火烧了七昼夜。改造后的阿如承接世界树储存信息的职责，纳西妲也脱离危险，火神之心却下落不明。须弥人开始修复家园，柯莱成为正式巡林员。她随旅行者回访蒙德时，尼可带利露帕尔来见她。镇灵替柯莱吸走花神残骸，随后散去，柯莱则回到道成林。\u003c/p\u003e\n","readingMinutes":2}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/As_All_Falls_to_Emptiness\"\u003e第九幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Truth_Amongst_the_Pages_of_Purana\"\u003e第十幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%A9%BA%E6%9C%88%E4%B9%8B%E6%AD%8C\"\u003e空月之歌中文幕名与任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E8%99%9A%E7%A9%BA%E5%8A%AB%E7%81%B0%E5%BE%80%E4%B8%96%E4%B9%A6\"\u003e「虚空劫灰往世书」中文任务正文\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E4%BD%A0%E7%9A%84%E5%BE%80%E4%BA%8B%E5%A6%82%E4%B8%80%E5%BA%A7%E8%8A%B1%E5%9B%AD\"\u003e「你的往事如一座花园」任务正文：柯莱与利露帕尔\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.7","major":6,"minor":7,"title":"无新增魔神任务：桑多涅归乡与望月者计划","chapter":"无主线","sections":[{"id":"v6.7-s0","title":"枫丹：发条人偶回家","kind":"chapter","html":"\u003cp\u003e桑多涅曾在与「博士」的决战中挡在旅行者身前，机关之躯几乎尽毁。众人以为「木偶」已经死去，她却在枫丹重新启动：残存的核心与新显现的「星之楔」给了她第二次机会。她修补躯体，把普隆尼亚留下的算式纳入新身体，却发现核心里仍有无法靠计算消除的「错谬」。\u003c/p\u003e\n\u003cp\u003e枫丹的千灵节将至，芙宁娜等人正筹拍映影。桑多涅化名「吉约丹」回到故乡，借维恩歌莱号和水下勘察寻找阿兰·吉约丹晚年的旧居。旅行者与派蒙在那里与她重逢。她接受两人同行，仍回避哥伦比娅，将内心反复出现的情绪视作需要排除的故障。\u003c/p\u003e\n\u003cp\u003e他们终于找到藏在水下的屋宅，屋内仍保存着花园、壁炉、工作台与旧照片。阿兰晚年仍为雷内的遭遇遗憾，也预见枫丹水位将会上升，提前留下防水机关。他为桑多涅准备了「多维立体算式核心」和一封信，告诉她自己珍视这段共同生活的时光，也希望她能借算式认识自己的内心。\u003c/p\u003e\n\u003cp\u003e桑多涅依照算式走入镜中的内心。她看见阿兰去世、旧日茶会的同伴离去、哥伦比娅走向月之门，以及普隆尼亚在决战中毁坏。这些记忆让她害怕再次失去朋友。她一度试图抹除承载哀伤的另一个自己，最后却击碎镜面，抱住了对方。\u003c/p\u003e\n\u003cp\u003e\u003cimg src=\"https://static.wikia.nocookie.net/gensin-impact/images/9/95/Story_Teaser-_What_Reflects_Itself_in_Mirror-Water_-_Genshin_Impact/revision/latest?cb=20260708040015\" alt=\"桑多涅拥抱镜中的自己，出自官方故事短片画面\" /\u003e\u003c/p\u003e\n\u003cp\u003e\u003cem\u003e官方故事短片画面：桑多涅拥抱被她视作「错谬」的自己。\u003c/em\u003e\u003c/p\u003e\n\u003cp\u003e桑多涅还察觉露景泉附近有游魂徘徊。它们曾被水仙十字结社的「断魂」之术割裂，无法归入地脉，后来又受怨意与污秽侵蚀。她与茜特菈莉、旅行者追查并净化游魂。映影拍摄临近结束时，她与哥伦比娅重逢，终于拥抱了对方；随后来到阿兰墓前，向他讲述自己归来的经历。\u003c/p\u003e\n","readingMinutes":2},{"id":"v6.7-s1","title":"霜月：望月者把声音送向星海","kind":"chapter","html":"\u003cp\u003e在挪德卡莱，旅行者与派蒙看见哥伦比娅的身影，追进杜南纳深坑附近的古设施。那身影其实是一只黑色月灵所化。它引他们启动遗迹，登上飞往霜月的船。旅行者称它为「黑蛋」。众人在霜月与哥伦比娅会合，穿过能源站、月海和废弃设施，继续寻找黑蛋要前往的地方。\u003c/p\u003e\n\u003cp\u003e月球背面仍立着严密守卫的龙族基地。记录称，归来的漆黑龙王曾将月心用作能源，把月球改造成对抗天理的武器，最终战败。基地深处还保存着伊比尼伯龙、乌吉恩、玛歌、卢沙里姆与宁宁等「望月者」的研究。他们曾探测星空，收到遥远文明的讯息，随后决定向星海回应，留下自己的名字与问候。\u003c/p\u003e\n\u003cp\u003e到达月心后，黑蛋得知自己由月球意志利用望月者留下的信息孕育，继承了他们的记忆与传讯使命。穿越虚假之天的信号可能暴露提瓦特的位置，旅行者与哥伦比娅因此犹豫，黑蛋也愿意为朋友放弃。哥伦比娅提出以月神之力掩护信号，出现危险便将它抹除，众人随后一同前往高塔。\u003c/p\u003e\n\u003cp\u003e黑蛋向星空报出望月者的名字，发出问候。传讯结束，她的形体散去，只留下帽子。古老终端随之播放一段回信：很久以前，仍在星海间旅行的双子曾收到望月者的声音，并约定有一天循声来访。信号因年代与距离而残缺，如今才在月球上重新被听见。旅行者认出那段旧日声音，收下黑蛋留下的帽子。\u003c/p\u003e\n","readingMinutes":2},{"id":"v6.7-s2","title":"三月旧影：无人船","kind":"chapter","html":"\u003cp\u003e霜月上另有三艘无人驾驶的月船。旅行者登船时，听见三位旧日月之女神的回忆。她们受龙王所托守护世界，后来为回应人类化作人形，还曾偷偷参加人间节庆。其中一位与伊斯塔露谈起时间法则；三姐妹也为高天秩序造成的伤亡争执，试图寻找能多救下一些生命的办法。\u003c/p\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/Luna_VIII\"\u003e6.7「月之八」版本内容与任务清单\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Sunny_Summer_Fontinalia\"\u003e「映夏！归乡？千灵节！」任务目录\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Those_We_Have_Lost_(Quest)\"\u003e「那些我们所失去的」任务正文\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/File:Story_Teaser-_What_Reflects_Itself_in_Mirror-Water_-_Genshin_Impact\"\u003e官方故事短片画面图库条目\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%9C%9B%E6%9C%88%EF%BC%88%E7%B3%BB%E5%88%97%E4%BB%BB%E5%8A%A1%EF%BC%89\"\u003e「望月」系列任务中文目录\u003c/a\u003e；\u003ca href=\"https://wiki.biligame.com/ys/%E6%9C%9B%E6%9C%88%E8%80%85%E8%AE%A1%E5%88%92\"\u003e「望月者计划」中文任务正文\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Moon_Gazing\"\u003e英文剧情概要\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Unmanned_Vessel\"\u003e「无人船」三段任务正文\u003c/a\u003e：\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Unmanned_Vessel_(I)\"\u003e其一\u003c/a\u003e、\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Unmanned_Vessel_(II)\"\u003e其二\u003c/a\u003e、\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Unmanned_Vessel_(III)\"\u003e其三\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"7.0","major":7,"minor":0,"title":"第七章第一至二幕：无神怜爱的雪国／死魂灵的夜曲","chapter":"第七章第1至2幕","sections":[{"id":"v7.0-s0","title":"第一幕：无神怜爱的雪国","kind":"chapter","html":"\u003ch3\u003e风雪中的来客\u003c/h3\u003e\n\u003cp\u003e离开挪德卡莱之前，哥伦比娅为旅行者和派蒙送行。旅途一路向北，终于抵达七国中最后一国——至冬。冰雪尚未给他们一个落脚的机会，派蒙便开始虚弱。狂风将二人冲散；旅行者跌入废弃列车所在的深谷，唤醒了古老装置「灰眸」。它认出旅行者是降临者，以日后相助为条件，借臻冰造物之力带旅行者穿过险境。\u003c/p\u003e\n\u003cp\u003e旅行者在雪屋中找到昏睡的派蒙，旁边守着一名有坎瑞亚星瞳的陌生人。那人没有回答自己的身份与派蒙的来历，只催旅行者先照顾她，便消失在风雪里。派蒙醒后认出他是愚人众的统括者「丑角」皮耶罗，却不记得自己与他曾有何交集。旅行者暂缓觐见女皇的打算，先带派蒙求医。\u003c/p\u003e\n\u003cp\u003e灰眸驱动旧列车，载两人抵达凝露镇。镇民缺少取暖的晶矿，店铺闭门，寒冷仿佛从街巷渗进了每个人的生活。猎人阿罗夏收留派蒙，也让旅行者看到这片雪国的另一面：冰之女皇推行「严冬计划」，从民间压缩能源供应，将力量集中到一项重要研究；地方官员却趁分配之机私藏晶矿。旅行者与阿罗夏搜集证据，使贪墨者被捕，让原本属于居民的燃料回到他们手中。\u003c/p\u003e\n\u003cp\u003e前往皇都的列车意外坠入「影域」——一片缺少风、光和常规元素力的异境。灰眸替旅行者重整装备，帮助众人击退魔物、返回地面。\u003c/p\u003e\n\u003ch3\u003e皇都与严冬计划\u003c/h3\u003e\n\u003cp\u003e列车驶进至冬堡。医生暂将派蒙的病视为受寒，药物却没能彻底驱散她的虚弱。旅行者寻访愚人众，从桑多涅处得知「公子」达达利亚如今还要代表属下参与至冬皇都评议会。桑多涅虽不愿陷在政事中，仍带旅行者前往彩冰镇救援矿工。在崩塌的矿洞里，旅行者与愚人众成员奥黛塔并肩击退魔物；一股新力量在旅行者手中凝成剑。其后，旅行者来到冰之七天神像前，终于与至冬的冰元素共鸣。\u003c/p\u003e\n\u003cp\u003e阿罗夏把旅行者引向秘密组织「呼啸社」。它的成员隐于普通职业之下，追查权势人物如何浪费或挪用国家的能源。剧院歌者沃雅妮莎也是其中一员。经她牵线，旅行者见到研究者米提亚，听说军械宫的实验正在大量消耗晶矿，试图从「星之楔」中获取新的能源。研究者已经出现难以解释的失忆；米提亚说到研究最终用途时，又被颈间异物强行阻断。派蒙则感到军械宫方向有某种力量正在影响自己。严冬计划的代价已经人人看见，真正的目的仍被封在高墙之内。\u003c/p\u003e\n\u003cp\u003e旅行者旁听了至冬皇都评议会。普契涅拉以全国用能为依据主张继续计划；达达利亚质问偏远地区和愚人众家属为何分得更少；潘塔罗涅则以维持大局回应。投票最终让计划以较窄优势延续。与此同时，神秘的「莱莱可」正通过潜入和威胁迫使权贵倒向反对票。桑多涅与达达利亚怀疑她就是奥黛塔：她的父亲曾在严冬计划早期死去，母亲从此再不能登台。旅行者持达达利亚的票，赴剧院观看奥黛塔的芭蕾试演，打算当面问清她的选择。\u003c/p\u003e\n","readingMinutes":3},{"id":"v7.0-s1","title":"第二幕：死魂灵的夜曲","kind":"chapter","html":"\u003ch3\u003e被风雪封住的舞台\u003c/h3\u003e\n\u003cp\u003e剧院上演《寻灵》。表演结束，暴风雪封住所有出口，观众与演员只得留宿。夜里，旅行者梦见黑雾追过螺旋楼梯，两人停下，随即被吞没。翌晨，梦中的两人果然死去，身上却没有寻常凶杀的痕迹。奥黛塔面对猜疑，公开承认自己就是「莱莱可」；她要揭露能源分配的不公，却与剧院中的死亡无关。风雪仍不止息，黑雾的梦一夜接着一夜，清晨的死者也一夜接着一夜。\u003c/p\u003e\n\u003cp\u003e众人查到一名没有入场票的佣兵施拉姆。他记忆中的至冬还停在数百年前，直到此时才忆起自己曾为保护恋人死在剧院。他是地脉留下的旧日亡魂，选择独自走进暴雪，希望断绝死亡；第二天的惨剧却仍发生。研究者米提亚也被奥黛塔目睹过死亡，却像活人一样走动，而且不记得死去的瞬间。他于是冒险离开，寻找剧院之外的真相。\u003c/p\u003e\n\u003cp\u003e剧院中还有被称作「冬妮娅」的少女。旅行者从未见过达达利亚的妹妹，旁人的记忆又各有缺口。真相揭开时，她忆起自己其实是很久以前因病死去的塔诗佳；工厂主楚古诺夫早已看出端倪，却因自己失去女儿，不忍拆穿。少女与众人告别。此后，沃雅妮莎也在死境中为守护旅行者耗尽力量，身影随之消散。\u003c/p\u003e\n\u003ch3\u003e死之执政的目光\u003c/h3\u003e\n\u003cp\u003e米提亚从暴雪中归来，提出骇人的推断：剧院里的人或许都已死去，只是不知道自己身在何处。他手上的红眼印记，使旅行者认出「死之执政」若娜瓦的象征。同行多日的阿罗夏忽然变了声调；借他形貌站在众人面前的，正是若娜瓦。她把剧院变作观看死亡之戏的场所，也让众人落入「死之诅咒」。地脉原本能牵引灵魂，剧院附近经改造的地脉却妨碍她处理死者；降临者的灵魂又不能像提瓦特之人那样被纳入地脉。旅行者与米提亚反击她的显现，众人才从那场如梦的死境中醒来。\u003c/p\u003e\n\u003cp\u003e醒来后，米提亚确认，剧院众人经历过死亡，又因尚不明的原因复活；多数人已遗忘死境里的经历，旅行者与米提亚仍记得。沃雅妮莎也已回到现实。旅行者还得知，皮耶罗已将派蒙带往军械宫救治。旅行者与奥黛塔赶去时，死之诅咒再次发动，众人接连倒下。奥黛塔的「燃珀」为旅行者指引灵魂，使旅行者先一步找回肉身醒来。若娜瓦亲自向派蒙伸手，皮耶罗挡住了她；旅行者也奋力出剑，以风元素留下一道浅伤。军械宫中的人开始复活，若娜瓦随即离开。\u003c/p\u003e\n\u003cp\u003e皮耶罗终于说出他所知的旧事：派蒙来自天空岛，曾被带到坎瑞亚，作为礼物献给国王伊尔明。她经历过五百年前的大灾变，自己却没有那段记忆。皮耶罗如今将她视作坎瑞亚旧时代留存的同伴，若娜瓦则称她没有天空岛的权能。治疗结束后，旅行者终于与康复的派蒙重逢。\u003c/p\u003e\n\u003cp\u003e\u003cimg src=\"https://patchwiki.biligame.com/images/ys/thumb/a/a1/7l9fnlyb0s0o6d9y0ot7btvotbc3h7s.png/1100px-%E9%AD%94%E7%A5%9E%E4%BB%BB%E5%8A%A1-%E6%A7%B2%E5%AF%84%E7%94%9F-CG1-%E7%A9%BA.png\" alt=\"旅行者在军械宫与派蒙重逢，游戏内《槲寄生》剧情画面\" /\u003e\u003c/p\u003e\n\u003cp\u003e\u003cem\u003e游戏内剧情 CG：历经剧院死境后，旅行者终于回到派蒙身边。画面采用旅行者「空」的版本。\u003c/em\u003e\u003c/p\u003e\n\u003cp\u003e米提亚说明「槲寄生计划」的危险：一旦技术突破有可能威胁天空岛，死之诅咒便会降下，使附近的人短暂死去，又在复生后失去记忆。剧院之祸正与他在表演时触及新的研究思路有关。皮耶罗同意暂缓计划，直到能对付若娜瓦；他也坦言愚人众与女皇要挑战天理。为了保护派蒙，旅行者选择暂与他们站在同一战线上。皮耶罗向二人展示了名为「槲寄生」的武器：严冬计划集中全国资源，挪德卡莱的研究制造它，军械宫则从第三降临者与星之楔的相关能量中寻找足以对抗天空岛的力量。\u003c/p\u003e\n\u003cp\u003e风雪暂时平息。严冬计划暂停，楚古诺夫关闭了吞噬能源的工厂。真正的猎人阿罗夏回到呼啸社，与复生的沃雅妮莎商议组织后续，宣布停用「莱莱可」代号，让奥黛塔暂时停职。奥黛塔则在「女士」墓前告别旧日师长。旅行者与派蒙在街头再见达达利亚及真正的冬妮娅。人群忽然欢呼：冰之女皇结束东行讨伐，带着侍从回到至冬堡。她没有对旅行者说话，径直走向宫殿。\u003c/p\u003e\n","readingMinutes":4},{"id":"v7.0-s2","title":"重要世界任务：灰眸与古代沙皇的遗业","kind":"world","html":"\u003cp\u003e列车上的同伴「灰眸」请旅行者寻找自己被分离的三份力量。线索先通向白桦雪葬的旧王宫：这里曾是白沙皇（Belyi Tsar）的居所，后来成为他的陵墓。传说他曾让人类与雪国异族同入宫廷，点燃为至冬带来温暖的火；约五百年前，他在抵御深渊与兽潮时战死，遗体归葬，部分血肉与「沙皇的白桦」相连。宫殿之下，旅行者发现秘密研究设施，记录中留有以生命炼金制造异兽的痕迹。守墓的双首兽兹韦尔曾受沙皇庇护，数百年来仍守在旧主身旁。它警告旅行者，灰眸失去的记忆中藏着危险。\u003c/p\u003e\n\u003cp\u003e另一份力量埋在焰羽谷的奥库罗夫。旅行者把头上长出枝杈的少女娜丝佳（Nastya）送回故乡，却发现整座镇正被「医生」改造成树一样的生命。孩子把怪异的树人叫作家人，把同化称为回家；不合群的人则会被当作害虫。所谓「医生」其实是生物炼金术士柯西（Koshchei），他以「完美之树」许诺没有争执和痛苦的永生，代价是人的语言、意志与独特的爱逐渐消失。娜丝佳明知外面还有未来，仍为了再见母亲而走向树心，化作其中的一部分。旅行者无法替她作选择，只能见证这份悲愿如何被永恒的承诺吞没。此后，曾侍奉古代沙皇的阿克西妮娅现身；她与柯西都曾参与创造「灰眸」，并催促旅行者让它取回力量。\u003c/p\u003e\n\u003cp\u003e第三份力量在公主帕芙琳娜（Pavlina）手中。她希望用它完成仪式，弥补雪国异族作为古代人造生命的缺陷。旅行者与阿克西妮娅登上霜峰阻止仪式。帕芙琳娜质问阿克西妮娅，为何她许诺的理想国容不下自己的族人；阿克西妮娅则坚持，这份力量应留给改变整个世界的计划。帕芙琳娜最终消散，碎片回到灰眸手中。\u003c/p\u003e\n\u003cp\u003e三份碎片齐聚，众人来到「无忧庭院」。阿克西妮娅揭开计划的真容：「灰眸」本是能完成「原初之人」的钥匙；那具躯壳，则与古代沙皇遗留下的身体和更古老的龙族血肉有关。旧时代的实验曾使一片国土坠入影域，让至冬陷入酷寒；如今她还想让整个世界进入影域，冻结时间对爱、喜悦与相聚的侵蚀。她许诺一个没有痛苦和嫉妒的明天，却也要让生命不再改变。\u003c/p\u003e\n\u003cp\u003e力量归位后，灰眸恢复为「原初之人」。它早已预见阿克西妮娅会将自己排除在理想国之外，因此拆散力量，为日后阻止她留下机会。旅行者仍须面对她与原初之人的力量，旧列车则依灰眸预留的最终协议赶来，帮助旅行者接近巨躯背后的弱点。决战结束，阿克西妮娅与原初之人一同沉入影域。旅行者与派蒙回到地面，再呼唤灰眸时，装置只剩机械的应答。\u003c/p\u003e\n","readingMinutes":3},{"id":"v7.0-s3","title":"此时悬而未决","kind":"question","html":"\u003cul\u003e\n\u003cli\u003e严冬计划与「槲寄生计划」究竟要怎样挑战天理？皮耶罗展示的武器会付出什么代价？\u003c/li\u003e\n\u003cli\u003e若娜瓦为何盯上派蒙？派蒙从天空岛来到坎瑞亚之后，又经历了什么？\u003c/li\u003e\n\u003cli\u003e影域、灰眸和至冬的新技术，与旧世界的规则究竟有多深的联系？\u003c/li\u003e\n\u003c/ul\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/7.0\"\u003e7.0 版本内容与任务清单\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%97%A0%E7%A5%9E%E6%80%9C%E7%88%B1%E7%9A%84%E9%9B%AA%E5%9B%BD\"\u003e第七章第一幕中文任务目录\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Everwinter_Without_Mercy\"\u003e第一幕英文剧情概要\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%AD%BB%E9%AD%82%E7%81%B5%E7%9A%84%E5%A4%9C%E6%9B%B2%EF%BC%88%E7%B3%BB%E5%88%97%E4%BB%BB%E5%8A%A1%EF%BC%89\"\u003e第七章第二幕中文任务目录\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Wraith%27s_Nocturne\"\u003e第二幕英文剧情概要\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%A7%B2%E5%AF%84%E7%94%9F\"\u003e「槲寄生」中文任务正文与剧情 CG\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/On_One_Side_a_Palace,_On_the_Other_a_Tomb\"\u003e「一边是宫殿一边是陵阙」剧情概要\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/In_the_Dwelling_of_Life\"\u003e「在生命的寓所」剧情概要\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Hesperides_of_Love_and_Hate\"\u003e「爱憎的赫斯珀利德斯」任务目录\u003c/a\u003e与\u003ca href=\"https://genshin-impact.fandom.com/wiki/Bell_Ringing_at_Dusk\"\u003e终章正文\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Her_Palace_Collapses_Into_the_Blizzard\"\u003e「她的宫殿正坍塌向风雪」剧情概要\u003c/a\u003e；\u003ca href=\"https://wiki.biligame.com/ys/%E5%A5%B9%E7%9A%84%E5%AE%AB%E6%AE%BF%E6%AD%A3%E5%9D%8D%E5%A1%8C%E5%90%91%E9%A3%8E%E9%9B%AA\"\u003e中文任务目录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%9B%BE%E4%B8%BA%E7%81%B5%E9%AD%82%E7%9A%84%E6%9C%A8%E8%88%9F\"\u003e「曾为灵魂的木舟」中文任务流程\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"7.1","major":7,"minor":1,"title":"第七章第三至四幕：白夜似梦初醒／往冥府的安魂歌","chapter":"第七章第3至4幕","sections":[{"id":"v7.1-s0","title":"第三幕：白夜似梦初醒","kind":"chapter","html":"\u003ch3\u003e觐见冰之女皇\u003c/h3\u003e\n\u003cp\u003e达达利亚为旅行者申请觐见。女仆长达妮卡先在餐厅试探旅行者的立场与身手，冬契军司令官、风仙薇斯纳及时制止了交锋。翌日，旅行者进入至冬宫，终于见到冰之女皇安娜丝塔夏。\u003c/p\u003e\n\u003cp\u003e女皇带旅行者查看第三降临者留下的封印。只有神之心能使它产生反应，她因而希望集齐由第三降临者遗骨制成的七颗神之心，打开封印。如今火神之心下落不明，里面的秘密仍无法探知。她也谈到自己的「慈爱」权能：在她看来，天理将爱人类的本能强加给魔神，使这份感情失去了自由；她拒绝依靠它治理至冬。由于自身记忆曾遭干预，她还每日用誊录棱晶保存记忆，借第三降临者的力量抵御世界规则的影响。\u003c/p\u003e\n\u003ch3\u003e生之印的征集\u003c/h3\u003e\n\u003cp\u003e皮耶罗利用「溯见之镜」，关联米提亚身上的死之印记与薇斯纳继承的生之权能，窥见两位执政的谈话。天理沉眠期间，天空岛仍会定期监测执政的行为。若娜瓦使触及禁限的研究者死亡，莱茵多特则赶在下一次监测前将他们复活，两人借此封锁至冬的技术，又避开擅杀人类的惩罚。研究者在反复死亡中丧失记忆，灵魂也逐渐受损。\u003c/p\u003e\n\u003cp\u003e薇斯纳的祖先曾受托保管少量生之权能。受桑多涅启发，她用这份力量提取与美好回忆相连的「生之印」，尝试汇聚众人的生命力抵抗死亡。提取的损耗很小，印记一旦破损，其中的回忆却可能消失。冬契军率先参与，北国银行随后向民众开放征集；旅行者与阿罗夏、奥黛塔、沃雅妮莎等人前往彩冰镇，将居民捐出的生之印带回。\u003c/p\u003e\n\u003ch3\u003e北国银行地下\u003c/h3\u003e\n\u003cp\u003e城中有人兜售延寿服务，众人循线发现，银行内部有人挪用生之印。旅行者与薇斯纳潜入金库，遇见正在调查的潘塔罗涅，又遭莱茵多特的失控实验体袭击。薇斯纳为保护印记透支力量，终于引来莱茵多特；她回收失窃的生之权能，将尚存的生之印归还原主。\u003c/p\u003e\n\u003cp\u003e女皇与潘塔罗涅早已料到，大规模征集会迫使藏在幕后的生之执政露面，因此顺势推动了消息传播。莱茵多特明确拒绝协助他们对抗若娜瓦。女皇随即以失踪的空间之执政阿斯莫代的情报为筹码，邀她七天后来至冬宫交换信息。薇斯纳失去大部分传承力量，女皇仍让银行归还那盏留有少量权能的明灯，替她保存了一份陪伴。\u003c/p\u003e\n","readingMinutes":2},{"id":"v7.1-s1","title":"第四幕：往冥府的安魂歌","kind":"chapter","html":"\u003ch3\u003e邪眼与贤者的笔记\u003c/h3\u003e\n\u003cp\u003e阿蕾奇诺协助皮耶罗改良邪眼，希望借赤月残存的死亡力量迎战若娜瓦。实验引入了赤月的其他权能，导致幻觉与深渊侵蚀，旅行者及时净化污染，保住她的身体。阿蕾奇诺指出，即便消除副作用，现有增幅仍不足以对抗执政，研究必须寻找新的突破。\u003c/p\u003e\n\u003cp\u003e旅行者再次接触溯见之镜，意外看见皮耶罗年轻时与「贤者」海洛塔帝求学的记忆。当年海洛塔帝找到延续老师生命的办法，却在最后关头放弃，皮耶罗一直将此视为背叛。经在任执行官全票同意，众人解封贤者留下的笔记，才发现那项成果会让人承受无尽折磨；海洛塔帝曾称它为「不死祝福」，后来亲手改作「不死诅咒」。\u003c/p\u003e\n\u003cp\u003e笔记中还保存着海洛塔帝舍弃前的最后人性。皮耶罗进入那段可以交谈的记忆，与昔日同窗重新讨论邪眼。两人推导出以使用者的生命与灵魂换取瞬间爆发的方案，皮耶罗决定凭自身的不死诅咒承受代价，制造「愚人之眼」。旅行者也从这次交谈中追问血亲的来历。皮耶罗确认：当年自己从天空岛召来了派蒙，海洛塔帝则在同一时期召来了旅行者的血亲。\u003c/p\u003e\n\u003ch3\u003e两处战场\u003c/h3\u003e\n\u003cp\u003e约定的日子到来，女皇在至冬宫接待莱茵多特；旅行者与盟友则在曙光车站准备迎战。戴因斯雷布应皮耶罗之邀赶到，他也希望向降下不死诅咒的若娜瓦讨回旧债。\u003c/p\u003e\n\u003cp\u003e宫中的谈话触及女皇被抹去的过去。莱茵多特称，坎瑞亚人诞生于女皇与第三降临者融合的血脉；两人曾受白沙皇唆使打开深渊之门，女皇随后遭天理抹消。第三降临者以自己的生命交换她复活，并要求天理保护他们的后裔，又留下违约便会生效的诅咒。天理复活女皇，同时抹去了世间关于第三降临者的记忆。女皇据此推断，坎瑞亚灾变触发了诅咒，才使天理陷入沉眠。\u003c/p\u003e\n\u003cp\u003e车站的战斗很快陷入绝境。若娜瓦动用权能，众人一度落入死后世界。旅行者返回后继续拖住她，戴因斯雷布与携愚人之眼赶来的皮耶罗也加入牵制。若娜瓦发现复活迟迟没有发生，试图离开战场，却被三人拦下。\u003c/p\u003e\n\u003cp\u003e女皇已借六颗神之心增幅冰元素力，减慢至冬宫大厅内的时间流速。莱茵多特只觉茶会过去片刻，外界却已逼近天空岛的监测时刻。来不及复活死者的若娜瓦因此被判违规，失去死亡权能；莱茵多特则必须依指令救回众人。女皇拒绝让参战者成为弃子，也终于使对方承认自己遭到了算计。\u003c/p\u003e\n\u003ch3\u003e胜利与遗赠\u003c/h3\u003e\n\u003cp\u003e若娜瓦失去权能后仍有强大的战力，转而全力攻击众人。旅行者与戴因斯雷布为皮耶罗创造机会，愚人之眼最终命中若娜瓦，使她从战场消失。军械宫随后确认，封锁研究的死之诅咒已经解除，槲寄生计划得以继续。皮耶罗活了下来，精神与灵魂却受到严重损耗；他和戴因身上五百年前的不死诅咒仍然存在。\u003c/p\u003e\n\u003cp\u003e女皇召见并表彰参战者。战场之外，重伤的若娜瓦来到至冬的判罚之钉旁，将藏于影域的「地原胚质」与之融合，企图让自己临近死亡的感受随「圣土化」扩散。\u003c/p\u003e\n","readingMinutes":3},{"id":"v7.1-s2","title":"尾声：异象","kind":"chapter","html":"\u003cp\u003e蒙德、璃月、稻妻、须弥、纳塔与至冬的六枚天钉同时亮起，光柱悬在各地天空。旅行者分别拜访阿贝多、魈、八重神子、迪希雅与坎蒂丝、玛薇卡和阿罗夏，查看异变。\u003c/p\u003e\n\u003cp\u003e阿贝多开始观察雪山天钉对周围环境的影响；魈奉钟离之命监视层岩巨渊；八重神子来到鹤观调查天光。沙漠中的迪希雅与坎蒂丝协助守望村落，玛薇卡留意纳塔上空，阿罗夏则在白桦雪葬附近观察判罚之钉的光芒与异响。各地都已采取行动，异变的后果仍未明朗。\u003c/p\u003e\n","readingMinutes":1},{"id":"v7.1-s3","title":"此刻悬而未决","kind":"question","html":"\u003cul\u003e\n\u003cli\u003e第三降临者的封印里留下了什么？失踪的火神之心在哪里？\u003c/li\u003e\n\u003cli\u003e血亲为何曾在天空岛，又为何响应海洛塔帝的召唤？\u003c/li\u003e\n\u003cli\u003e若娜瓦留下的地原胚质会引发什么？女皇的反抗将如何继续？\u003c/li\u003e\n\u003c/ul\u003e\n","readingMinutes":1}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://ys.mihoyo.com/main/m/news/detail/166253\"\u003e7.1 官方魔神任务与尾声开放公告\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%99%BD%E5%A4%9C%E4%BC%BC%E6%A2%A6%E5%88%9D%E9%86%92\"\u003e第三幕「白夜似梦初醒」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E6%BA%AF%E8%A7%81%E5%85%89%E5%BD%B1%E4%BA%A4%E7%BB%87\"\u003e溯见光影交织\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E6%98%9F%E7%81%AB%E4%BA%A4%E6%B1%87%E4%BA%8E%E5%86%BB%E5%8E%9F\"\u003e星火交汇于冻原\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BB%85%E6%AD%A4%E4%B8%80%E7%9D%80\"\u003e仅此一着\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C\"\u003e第四幕「往冥府的安魂歌」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E9%82%AA%E7%9C%BC%EF%BC%88%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C%EF%BC%89\"\u003e邪眼\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E8%A2%AB%E9%95%8C%E5%88%BB%E7%9A%84%E6%97%B6%E5%85%89\"\u003e被镌刻的时光\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BA%8E%E9%A5%AF%E5%88%AB%E4%B9%8B%E6%97%B6%E6%95%A3%E8%90%BD%E7%9A%84%E9%BB%91%E7%BE%BD\"\u003e于饯别之时散落的黑羽\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://allthings.how/genshin-impact-7-1-anomaly-epilogue-all-six-celestial-nail-quest-locations/\"\u003e「异象」六地任务与对话位置记录\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"}]};
